/**
 * The source's module-level document listeners (click / input / change / keydown). As for HR, they are registered the
 * first time the Billing window mounts (biInstallGlobal), after the OS menu's outside-click listener, which the source
 * also adds first (L11708); the handlers only act inside the Billing window.
 */
const pendingGlobal: (() => void)[] = [];
const onDoc = <K extends keyof DocumentEventMap>(ev: K, fn: (e: DocumentEventMap[K]) => void, cap?: boolean) => { pendingGlobal.push(() => document.addEventListener(ev, fn, cap)); };
let globalDone = false;
export function biInstallGlobal() { if (globalDone) return; globalDone = true; pendingGlobal.forEach((f) => f()); }

