function biFormState(inv: BiDoc){const f=inv.form;if(!f)return {ok:true,data:null};const data=inv.formData||{};const req=(f.req||[]);const ok=req.every(k=>String(data[k]??"").trim()!=="");return {ok,data,req}}

/* ---------- reporting (pure functions over the store) ---------- */
/* invoiced = issued invoices by issue date, minus credit notes by their own date. cash = payments with status ok by payment date, minus completed refunds by refund date. */
function biInRange(d: string,f: string,t: string){return (!f||d>=f)&&(!t||d<=t)}
function biDims(inv: BiDoc): Record<string, string | null | undefined>{return {prac:inv.prac,est:inv.est,payer:inv.payer||"self",party:inv.party,svc:(inv.snap?.lines||inv.lines)[0]?.svc||"-",cat:biSvc((inv.snap?.lines||inv.lines)[0]?.svc)?.cat||"-"}}
function biScope(inv: { prac?: string | null }){return biRole()!=="prac"||biCan("rep.all")?true:inv.prac===biMe()}
function biFacts(f: string,t: string,flt: Dict={}){const S=BI.st;const pass=(inv: BiDoc)=>biScope(inv)&&Object.entries(flt).every(([k,v])=>!v||biDims(inv)[k]===v);const out: BiFact[]=[];
  S!.invoices.forEach(inv=>{if(inv.status!=="issued"||!pass(inv))return;if(biInRange(inv.issue,f,t))out.push({k:"inv",d:inv.issue,amt:inv.snap!.tot.total,net:inv.snap!.tot.net,dims:biDims(inv),inv,lines:inv.snap!.lines})});
  S!.credits.forEach(c=>{const inv=biInv(c.inv);if(!inv||!pass(inv))return;if(biInRange(c.issue,f,t))out.push({k:"cn",d:c.issue,amt:-c.snap!.tot.total,net:-c.snap!.tot.net,dims:biDims(inv),inv,cn:c})});
  S!.payments.forEach(p=>{if(p.status!=="ok"||!biInRange(p.date,f,t))return;p.alloc.forEach(a=>{const inv=biInv(a.inv);if(!inv||!pass(inv))return;out.push({k:"cash",d:p.date,amt:a.amt,dims:Object.assign(biDims(inv),{method:p.method}),inv,pay:p})});const u=biUnapplied(p);if(u>0&&!Object.values(flt).some(Boolean)&&biRole()!=="prac")out.push({k:"cash",d:p.date,amt:u,dims:{method:p.method,prac:"-",est:"-",payer:"-",svc:"-",cat:"-"},pay:p,unapplied:true})});
  S!.refunds.forEach(r=>{if(r.status!=="done"||!biInRange(r.doneAt||r.date,f,t)||Object.values(flt).some(Boolean)||biRole()==="prac")return;out.push({k:"refund",d:r.doneAt||r.date,amt:-r.amount,dims:{method:r.method},rf:r})});
  return out}
function biSum(facts: BiFact[],k: string | string[]){return facts.filter(x=>Array.isArray(k)?k.includes(x.k):x.k===k).reduce((s,x)=>s+x.amt,0)}
/* receivables at a date: issued invoices on or before the date, balance computed with credits and payments dated on or before it */
function biReceivable(at: string,flt: Dict={}){const S=BI.st;let tot=0,over=0,n=0,no=0;S!.invoices.forEach(inv=>{if(inv.status!=="issued"||inv.issue>at||!biScope(inv))return;if(Object.entries(flt).some(([k,v])=>v&&biDims(inv)[k]!==v))return;
  const cr=S!.credits.filter(c=>c.inv===inv.id&&c.issue<=at).reduce((s,c)=>s+c.snap!.tot.total,0);let pd=0;S!.payments.forEach(p=>{if(p.status==="ok"&&p.date<=at)p.alloc.forEach(a=>{if(a.inv===inv.id)pd+=a.amt})});const b=inv.snap!.tot.total-cr-pd;if(b>0){tot+=b;n++;if(inv.due!<at){over+=b;no++}}});return {tot,over,n,no}}
/* period helpers */
function biPeriod(kind: string,ref?: string | null): [string, string]{const d=biD(ref||biToday());const y=d.getFullYear(),m=d.getMonth();const iso=(x: Date)=>biIso(x);
  if(kind==="day")return [iso(d),iso(d)];if(kind==="week"){const wd=(d.getDay()+6)%7;const a=new Date(d);a.setDate(d.getDate()-wd);const b=new Date(a);b.setDate(a.getDate()+6);return [iso(a),iso(b)]}
  if(kind==="month")return [iso(new Date(y,m,1,12)),iso(new Date(y,m+1,0,12))];if(kind==="quarter"){const q=Math.floor(m/3)*3;return [iso(new Date(y,q,1,12)),iso(new Date(y,q+3,0,12))]}return [iso(new Date(y,0,1,12)),iso(new Date(y,11,31,12))]}
function biPrevPeriod(kind: string,[f,t]: string[]): [string, string]{if(kind==="day")return [biAddDays(f,-1),biAddDays(t,-1)];if(kind==="week")return [biAddDays(f,-7),biAddDays(t,-7)];const back={month:1,quarter:3,year:12}[kind]||1;const f2=biAddMonths(f,-back);return biPeriod(kind,f2)}
/* practitioner allocation (reporting only; payroll stays in HR & Payroll) */
function biAllocate(f: string,t: string,basis: string){const S=BI.st;const facts=biFacts(f,t).filter(x=>basis==="cash"?x.k==="cash"&&!x.unapplied:(x.k==="inv"||x.k==="cn"));const by: Record<string, BiAllocRes>={};
  facts.forEach(x=>{const prac=x.dims.prac as string;const net=basis==="cash"?x.amt:x.net;const r=S!.alloc.find(a=>a.on!==false&&a.prac===prac&&(!a.svc||a.svc===x.dims.svc))||S!.alloc.find(a=>a.on!==false&&a.prac===prac&&!a.svc);const o=(by[prac]=by[prac]||{prac,base:0,share:0,rule:r?r.id:null,n:0});o.base+=net!;o.n++;
    if(r)o.share+=r.model==="pct"?biMulRound(net!,r.val,10000):(x.k==="inv"?r.val:x.k==="cn"?-r.val:0)});return Object.values(by)}

