  const swap=()=>{R.querySelector<HTMLInputElement>(".bi-hd")!.outerHTML=biHeadHTML();const npg=R.querySelector<HTMLInputElement>(".bi-pg");npg!.dataset.pg=view;npg!.innerHTML=biPageHTML();npg!.scrollTop=0;const nl=R.querySelector<HTMLInputElement>(".bi-nl");const st=nl?.scrollTop||0;R.querySelector<HTMLInputElement>(".bi-nav")!.outerHTML=biNavHTML();R.querySelector<HTMLInputElement>(".bi-nl")!.scrollTop=st;R.querySelector<HTMLInputElement>(".bi-scrim")!.classList.remove("on");biMount();requestAnimationFrame(()=>{biInk(true);R.querySelector<HTMLInputElement>('.bi-nl [aria-current="page"]')?.scrollIntoView?.({block:"nearest"})});biEnter(npg)};
