/* cols: [{k, l, v:row=>sortable value, h:row=>html, csv:row=>text, num:true, w, hide:true}] */
function biTblState(id: string,def?: BiTblOpts){const T=BI.ui.tables;if(!T[id]){const saved=(BI.st!.set.cols||{})[id];T[id]=Object.assign({sort:def?.sort||null,dir:def?.dir||-1,page:0,size:def?.size||25,hidden:saved||def?.hidden||[]},{})}return T[id]}
function biTable<R extends BiRow>(id: string,cols: BiCol<R>[],rows: R[],o: BiTblOpts<R>={}){const T=biTblState(id,o);const rs=rows.slice();const sc=cols.find(c=>c.k===T.sort);if(sc){const v=sc.v||(r=>(r as unknown as Bag)[sc.k]);rs.sort((a,b)=>{const x=v(a) as number,y=v(b) as number;return (x>y?1:x<y?-1:0)*T.dir})}
  const vis=cols.filter(c=>!T.hidden.includes(c.k));if(BI_TBL[id])BI_TBL[id].sorted=rs;const n=rs.length;const pages=Math.max(1,Math.ceil(n/T.size));if(T.page>=pages)T.page=pages-1;const pg=rs.slice(T.page*T.size,(T.page+1)*T.size);
  const SEL=o.sel?biSel(id):null;const head=(SEL?`<th class="ck"><input type="checkbox" data-biselall="${id}" aria-label="${biE(biW("all"))}"${pg.length&&pg.every(r=>SEL.includes(r.id))?" checked":""}></th>`:"")+vis.map(c=>`<th${c.num?' class="num"':""}${c.w?` style="width:${c.w}"`:""} aria-sort="${T.sort===c.k?(T.dir>0?"ascending":"descending"):"none"}">${c.nosort?biE(L4(c.l)):`<button type="button" data-bisort="${id}|${c.k}">${biE(L4(c.l))}${T.sort===c.k?bii(T.dir>0?"up":"down",12):""}</button>`}</th>`).join("");
  const body=pg.map((r,i)=>`<tr data-birow="${biE(o.key?o.key(r):r.id)}"${o.click?' tabindex="0"':""}${o.rowCls?` class="${o.rowCls(r)}"`:""} style="--i:${Math.min(i,14)}">${SEL?`<td class="ck"><input type="checkbox" data-bisel="${id}|${biE(r.id)}" aria-label="${biE(biW("sel"))}"${SEL.includes(r.id)?" checked":""}></td>`:""}${vis.map(c=>`<td${c.num?' class="num"':""}${c.cls?` class="${c.cls}"`:""}>${c.h?c.h(r):biE(c.v?c.v(r):(r as unknown as Bag)[c.k])}</td>`).join("")}</tr>`).join("");
  const foot=o.foot?`<tfoot><tr>${SEL?"<td></td>":""}${vis.map(c=>`<td${c.num?' class="num"':""}>${o.foot![c.k]??""}</td>`).join("")}</tr></tfoot>`:"";
  return `<div class="bi-tbl" data-bitbl="${id}"><div class="bi-tbtools">${SEL&&SEL.length?`<div class="bi-bulk"><b>${biNf(SEL.length)}</b> ${biE(biW("selected"))} ${o.bulk?o.bulk(SEL):""}<button type="button" class="bi-btn sm ghost" data-biselx="${id}">${bii("x",13)}</button></div>`:(o.tools||"")}<span class="sp"></span><span class="bi-mut sm">${biNf(n)} ${biE(biW("rows"))}</span>${o.csv!==false?`<button type="button" class="bi-btn sm" data-bicsv="${id}">${bii("dl",14)}${biE(biW("export"))}</button>`:""}<button type="button" class="bi-btn sm" data-bicols="${id}" aria-haspopup="menu">${bii("cols",14)}${biE(biW("cols"))}</button></div>
    <div class="bi-tbs"><table class="bi-tb${o.click?" click":""}"><thead><tr>${head}</tr></thead><tbody>${body||`<tr class="empty"><td colspan="${vis.length+(SEL?1:0)}">${biEmpty("search",o.empty||biW("empty"),o.emptyAct||"")}</td></tr>`}</tbody>${foot}</table></div>
    ${pages>1?`<div class="bi-pager"><button type="button" class="bi-btn sm" data-bipage="${id}|-1"${T.page?"":" disabled"}>${bii("back",14)}${biE(biW("prev"))}</button><span>${biNf(T.page+1)} ${biE(biW("of"))} ${biNf(pages)}</span><button type="button" class="bi-btn sm" data-bipage="${id}|1"${T.page<pages-1?"":" disabled"}>${biE(biW("next"))}${bii("chev",14)}</button></div>`:""}</div>`}
const biSel=(id: string)=>(BI.ui.sel=BI.ui.sel||{})[id]=(BI.ui.sel||{})[id]||[];
/* the table definitions are kept per page so CSV export and column menus can reach them */
const BI_TBL: Record<string, BiTblDef>={};
function biTblCsv(id: string){const t=BI_TBL[id];if(!t)return;const T=biTblState(id);const cols=t.cols.filter(c=>!T.hidden.includes(c.k));biDownload(`${id}-${biToday()}.csv`,biCsv(cols.map(c=>L4(c.l)),t.rows.map(r=>cols.map(c=>c.csv?c.csv(r):c.v?c.v(r):(r as unknown as Bag)[c.k]))))}
function biTblCols(id: string,btn: HTMLElement){const t=BI_TBL[id];const T=biTblState(id);const r=btn.getBoundingClientRect();osMenu(r.left,r.bottom+4,t.cols.filter(c=>!c.fixed).map(c=>({l:L4(c.l),check:!T.hidden.includes(c.k),run:()=>{const i=T.hidden.indexOf(c.k);if(i>=0)T.hidden.splice(i,1);else T.hidden.push(c.k);(BI.st!.set.cols=BI.st!.set.cols||{})[id]=T.hidden.slice();biSave();biRefresh()}})))}

/* ---------- filters bar shared by lists ---------- */
/* f: the page's filter object; keys: q, per, from, to, st, prac, est, payer, min, max */
const BI_PERS=[["","Toute période|Any time|Gesamter Zeitraum|كل الفترات"],["month","Ce mois-ci|This month|Dieser Monat|هذا الشهر"],["pmonth","Mois précédent|Last month|Letzter Monat|الشهر السابق"],["quarter","Ce trimestre|This quarter|Dieses Quartal|هذا الربع"],["year","Cette année|This year|Dieses Jahr|هذه السنة"],["p12","12 derniers mois|Last 12 months|Letzte 12 Monate|آخر 12 شهرًا"],["custom","Personnalisée…|Custom…|Benutzerdefiniert…|مخصص…"]];
function biPerRange(f: BiFlt){if(f.per==="custom")return [f.from||"",f.to||""];if(!f.per)return ["",""];if(f.per==="pmonth")return biPrevPeriod("month",biPeriod("month"));if(f.per==="p12")return [biAddMonths(biToday(),-12),biToday()];return biPeriod(f.per)}
function biFltHTML(key: string,f: BiFlt,o: BiFltOpts={}){const st=o.states||[];return `<div class="bi-flt" data-biflt="${key}">
  <label class="bi-srch">${bii("search",14)}<input type="search" data-bif="q" value="${biE(f.q||"")}" placeholder="${biE(o.ph||biW("search"))}"></label>
  <select class="bi-in sm" data-bif="per" aria-label="${biE(biW("period"))}">${biOpts(BI_PERS.map(([v,l])=>[v,L4(l)]),f.per||"")}</select>
  ${f.per==="custom"?`<input type="date" class="bi-in sm" data-bif="from" value="${biE(f.from||"")}" aria-label="${biE(biW("from"))}"><input type="date" class="bi-in sm" data-bif="to" value="${biE(f.to||"")}" aria-label="${biE(biW("to"))}">`:""}
  ${st.length?`<select class="bi-in sm" data-bif="st" aria-label="${biE(biW("status"))}">${biOpts(st.map(s=>[s,L4((BI_STATES[s]||[s])[0])]),f.st||"",{any:biW("status")+" : "+biW("any")})}</select>`:""}
  ${o.prac!==false&&biRole()!=="prac"?`<select class="bi-in sm" data-bif="prac" aria-label="${biE(biW("prac"))}">${biOpts(biPracOpts(),f.prac||"",{any:biW("prac")+" : "+biW("any")})}</select>`:""}
  ${o.est!==false?`<select class="bi-in sm" data-bif="est" aria-label="${biE(biW("est"))}">${biOpts(biEstOpts(),f.est||"",{any:biW("est")+" : "+biW("any")})}</select>`:""}
  ${o.payer?`<select class="bi-in sm" data-bif="payer" aria-label="${biE(biW("payer"))}">${biOpts(biPayerOpts(),f.payer||"",{any:biW("payer")+" : "+biW("any")})}</select>`:""}
  ${o.amount?`<input class="bi-in sm amt" data-bif="min" inputmode="decimal" value="${biE(f.min||"")}" placeholder="${biE(biW("min"))} ${biE(BI_CUR[biCur()].s)}" aria-label="${biE(biW("amount"))} ${biE(biW("min"))}"><input class="bi-in sm amt" data-bif="max" inputmode="decimal" value="${biE(f.max||"")}" placeholder="${biE(biW("max"))} ${biE(BI_CUR[biCur()].s)}" aria-label="${biE(biW("amount"))} ${biE(biW("max"))}">`:""}
  ${Object.entries(f).some(([k,v])=>v&&k!=="view")?`<button type="button" class="bi-btn sm ghost" data-bifreset="${key}">${bii("x",13)}${biE(biW("resetFlt"))}</button>`:""}
  ${o.views?biViewsHTML(key):""}</div>`}
function biViewsHTML(key: string){const vs=(BI.st!.set.views||[]).filter(v=>v.t===key);return `<span class="bi-views"><button type="button" class="bi-btn sm" data-biviews="${key}" aria-haspopup="menu">${bii("star",14)}${biE(biW("views"))}${vs.length?` <em>${vs.length}</em>`:""}</button></span>`}
const biFlt=(key: string)=>(BI.ui.flt=BI.ui.flt||{})[key]=(BI.ui.flt||{})[key]||{};
function biAmtIn(s: string | number | null | undefined){try{return biParseMoney(s)}catch(e){return null}}

/* ---------- side drawer (document preview + actions) ---------- */
function biDrawer(kind: string | null,id?: string){const R=biRoot();if(!R)return;const d=R.querySelector<HTMLInputElement>(".bi-drw");if(!kind){if(BI.ui.drawer){BI.ui.drawer=null;d!.classList.remove("open");d!.setAttribute("aria-hidden","true");R.querySelector<HTMLInputElement>(".bi-scrim")!.classList.remove("on");R.querySelectorAll<HTMLInputElement>("tr.bi-rsel").forEach(t=>t.classList.remove("bi-rsel"))}return}
  BI.ui.drawer={kind,id};biDrawerPaint();d!.classList.add("open");d!.setAttribute("aria-hidden","false");if(R.dataset.sz!=="l")R.querySelector<HTMLInputElement>(".bi-scrim")!.classList.add("on");R.querySelectorAll<HTMLInputElement>("tr.bi-rsel").forEach(t=>t.classList.remove("bi-rsel"));R.querySelector<HTMLInputElement>(`tr[data-birow="${CSS.escape(id!)}"]`)?.classList.add("bi-rsel");setTimeout(()=>d!.querySelector<HTMLInputElement>("[data-bidfocus],button")?.focus({preventScroll:true}),80)}
let biDrawerPaint=function(){const R=biRoot();const D=BI.ui.drawer;if(!R||!D)return;const d=R.querySelector<HTMLInputElement>(".bi-drw");const f=BI_DRAWERS[D.kind];if(!f){d!.innerHTML="";return}try{d!.innerHTML=f(D.id!)}catch(e){console.error(e);d!.innerHTML=`<div class="bi-err">${biE(biErr(e))}</div>`}biCountUp(d)}
const BI_DRAWERS: Record<string, (id: string) => string>={};

/* ---------- global search ---------- */
function biGsearch(q: string){q=q.trim().toLowerCase();if(q.length<2)return [];const S=BI.st;const out: BiGsHit[]=[];
  S!.invoices.forEach(i=>{if(!biScope(i))return;const s=((i.no||"")+" "+biPartyName(i.party)).toLowerCase();if(s.includes(q))out.push({k:"inv",id:i.id,t:i.no||L4(BI_STATES.draft[0]),s:biPartyName(i.party)+" · "+biM(biDocTotal(i),i.cur),st:biInvState(i)})});
  S!.parties.forEach(p=>{if(biPartyName(p.id).toLowerCase().includes(q))out.push({k:"party",id:p.id,t:biPartyName(p.id),s:L4(BIW.party)})});
  S!.payments.forEach(p=>{if((p.no+" "+p.ref).toLowerCase().includes(q))out.push({k:"pay",id:p.id,t:p.no,s:biPartyName(p.party)+" · "+biM(p.amount,p.cur),st:p.status})});
  S!.credits.forEach(c=>{if(c.no!.toLowerCase().includes(q))out.push({k:"cn",id:c.id,t:c.no!,s:biPartyName(c.party)})});return out.slice(0,12)}
function biGsPaint(inp: HTMLInputElement){const R=biRoot();const box=R!.querySelector<HTMLInputElement>("[data-bigsr]");const res=biGsearch(inp.value);if(!inp.value.trim()){box!.hidden=true;return}
  box!.innerHTML=res.length?res.map((r,i)=>`<button type="button" role="option" data-bigsk="${r.k}|${biE(r.id)}" aria-selected="${i===0}">${bii(({inv:"file",party:"user",pay:"card",cn:"credit"} as Dict)[r.k],15)}<span><b>${biE(r.t)}</b><small>${biE(r.s)}</small></span>${r.st?biSt8(r.st):""}</button>`).join(""):`<p class="bi-mut bi-pad">${biE(biW("empty"))}</p>`;box!.hidden=false}
function biGsOpen(k: string,id: string){const R=biRoot();R!.querySelector<HTMLInputElement>("[data-bigsr]")!.hidden=true;R!.querySelector<HTMLInputElement>("[data-bigs]")!.value="";
  if(k==="inv"){biGo("invoices");setTimeout(()=>biDrawer("inv",id),200)}else if(k==="party"){biGo("invoices",{q:biPartyName(id)})}else if(k==="pay"){biGo("transactions");setTimeout(()=>biDrawer("pay",id),200)}else if(k==="cn"){biGo("credits");setTimeout(()=>biDrawer("cn",id),200)}}

/* ---------- events ---------- */
onDoc("click",e=>{const R=biRoot();if(!R||!R.contains(tgt(e)))return;const c=(s: string)=>tgt(e).closest<HTMLInputElement>(s);let x;
  if(!c(".bi-gs"))R.querySelector<HTMLInputElement>("[data-bigsr]")?.setAttribute("hidden","");
  if((x=c("[data-bigo]"))){let a=x.dataset.biarg;try{a=a?JSON.parse(a):undefined}catch(_){}biGo(x.dataset.bigo!,a);return}
  if(c("[data-biback]")){biBack();return}
  if((x=c("[data-bitog]"))){const g=x.dataset.bitog;const box=x.parentElement;const open=!box!.classList.contains("open");BI.ui.open[g!]=open;box!.classList.toggle("open",open);x.setAttribute("aria-expanded",(open) as unknown as string);const nb=box!.querySelector<HTMLInputElement>(".bi-nb");if(open){nb!.hidden=false;if(!biRM())nb!.animate([{height:"0px",opacity:0},{height:nb!.scrollHeight+"px",opacity:1}],{duration:240,easing:"cubic-bezier(.2,.9,.3,1)"})}else if(biRM())nb!.hidden=true;else nb!.animate([{height:nb!.scrollHeight+"px"},{height:"0px",opacity:0}],{duration:200,easing:"ease-in"}).finished.then(()=>{if(!box!.classList.contains("open"))nb!.hidden=true});setTimeout(()=>biInk(false),260);return}
  if(c("[data-binav]")){BI.ui.navOpen=!BI.ui.navOpen;R.querySelector<HTMLInputElement>(".bi-nav")!.classList.toggle("open",BI.ui.navOpen);R.querySelector<HTMLInputElement>(".bi-scrim")!.classList.toggle("on",BI.ui.navOpen);return}
  if(c("[data-biscrim]")){BI.ui.navOpen=false;R.querySelector<HTMLInputElement>(".bi-nav")!.classList.remove("open");biDrawer(null);R.querySelector<HTMLInputElement>(".bi-scrim")!.classList.remove("on");return}
  if(c("[data-binew]")){biGo("editor",null);return}
  if((x=c("[data-birole]"))){const r=x.getBoundingClientRect();osMenu(r.left,r.bottom+4,[{html:`<div class="bi-menuh">${biE(biW("role"))}</div>`},...Object.entries(BI_ROLES).map(([k,v])=>({l:L4(v.n),check:biRole()===k,run:()=>{BI.st!.role=k;biLog("role.switch","sys","",L4(v.n));biSave();BI.ui.stack=[];biRender(true);biToast(biW("role")+" : "+L4(v.n))}})),"-",{l:L4("Le praticien simulé : |Simulated practitioner: |Simulierter Behandler: |الممارس المحاكى: ")+biPracName(biMe()),sub:BI.st!.pracs.map(p=>({l:p.name,check:biMe()===p.id,run:()=>{BI.st!.mePrac=p.id;biSave();biRender(true)}}))}]);return}
  if((x=c("[data-bigsk]"))){const [k,id]=x.dataset.bigsk!.split("|");biGsOpen(k,id);return}
  if((x=c("[data-bisort]"))){const [id,k]=x.dataset.bisort!.split("|");const T=biTblState(id);if(T.sort===k)T.dir*=-1;else{T.sort=k;T.dir=-1}T.page=0;biRefresh();return}
  if((x=c("[data-bipage]"))){const [id,d]=x.dataset.bipage!.split("|");biTblState(id).page+=+d;biRefresh();R.querySelector<HTMLInputElement>(`[data-bitbl="${id}"]`)?.scrollIntoView({block:"start",behavior:biRM()?"auto":"smooth"});return}
  if((x=c("[data-bisel]"))){const [id,rid]=x.dataset.bisel!.split("|");const S=biSel(id);const i=S.indexOf(rid);if(x.checked&&i<0)S.push(rid);if(!x.checked&&i>=0)S.splice(i,1);biRefresh();return}
  if((x=c("[data-biselall]"))){const id=x.dataset.biselall;const t=BI_TBL[id!];const S=biSel(id!);const T=biTblState(id!);const page=t.sorted!.slice(T.page*T.size,(T.page+1)*T.size).map(r=>r.id);if(x.checked)page.forEach(r=>{if(!S.includes(r))S.push(r)});else page.forEach(r=>{const i=S.indexOf(r);if(i>=0)S.splice(i,1)});biRefresh();return}
  if((x=c("[data-biselx]"))){BI.ui.sel![x.dataset.biselx!]=[];biRefresh();return}
  if((x=c("[data-bicsv]"))){biTblCsv(x.dataset.bicsv!);return}
  if((x=c("[data-bicols]"))){biTblCols(x.dataset.bicols!,x);return}
  if((x=c("[data-bifreset]"))){BI.ui.flt![x.dataset.bifreset!]={};Object.values(BI.ui.tables).forEach(t=>t.page=0);biRefresh();return}
  if((x=c("[data-biviews]"))){const key=x.dataset.biviews;const vs=(BI.st!.set.views||[]).filter(v=>v.t===key);const r=x.getBoundingClientRect();osMenu(r.left,r.bottom+4,[...vs.map(v=>({l:v.n,ic:bii("star",14),run:()=>{BI.ui.flt![key!]=biClone(v.f);biRefresh()},sub:[{l:biW("del"),danger:true,run:()=>{BI.st!.set.views=BI.st!.set.views.filter(z=>z!==v);biSave();biRefresh()}}]})),vs.length?"-":null,{l:biW("saveView")+"…",ic:bii("plus",14),run:()=>biPrompt(biW("viewName"),"",n=>{if(!n)return;(BI.st!.set.views=BI.st!.set.views||[]).push({t:key!,n,f:biClone(biFlt(key!))});biSave();biRefresh();biToast(biW("saved"))})}].filter(Boolean));return}
  if((x=c("[data-bidrw]"))){const [k,id]=x.dataset.bidrw!.split("|");biDrawer(k,id);return}
  if(c("[data-bidrwx]")){biDrawer(null);return}
  const row=c("tr[data-birow]");if(row&&!c("button,a,input,select,label")){const t=row.closest<HTMLInputElement>("[data-bitbl]")?.dataset.bitbl;const def=BI_TBL[t!];if(def?.open){def.open(row.dataset.birow!);return}}
  const P=BI_P[BI.ui.view];if(P?.click){P.click(e,c)}
},true);
onDoc("input",e=>{const R=biRoot();if(!R||!R.contains(tgt(e)))return;const x=tgt(e);
  if(x.matches("[data-bigs]")){biGsPaint(x);return}
  if(x.matches("[data-bif]")&&x.type!=="date"&&x.tagName!=="SELECT"){const key=x.closest<HTMLInputElement>("[data-biflt]")!.dataset.biflt;biFlt(key!)[x.dataset.bif!]=x.value;Object.values(BI.ui.tables).forEach(t=>t.page=0);clearTimeout(BI.fT);BI.fT=setTimeout(()=>{const pos=x.selectionStart;biRefresh();const n=R.querySelector<HTMLInputElement>(`[data-biflt="${key}"] [data-bif="${x.dataset.bif}"]`);if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(_){}}},180);return}
  BI_P[BI.ui.view]?.input?.(e)},true);
onDoc("change",e=>{const R=biRoot();if(!R||!R.contains(tgt(e)))return;const x=tgt(e);
  if(x.matches("[data-bif]")&&(x.tagName==="SELECT"||x.type==="date")){const key=x.closest<HTMLInputElement>("[data-biflt]")!.dataset.biflt;biFlt(key!)[x.dataset.bif!]=x.value;Object.values(BI.ui.tables).forEach(t=>t.page=0);biRefresh();R.querySelector<HTMLInputElement>(`[data-biflt="${key}"] [data-bif="${x.dataset.bif}"]`)?.focus();return}
  BI_P[BI.ui.view]?.change?.(e)},true);
onDoc("keydown",e=>{const R=biRoot();if(!R||!R.contains(tgt(e)))return;const x=tgt(e);
  if(x.matches("[data-bigs]")){const box=R.querySelector<HTMLInputElement>("[data-bigsr]");const its=[...box!.querySelectorAll<HTMLInputElement>("[data-bigsk]")];if(!its.length)return;const i=its.findIndex(b=>b.getAttribute("aria-selected")==="true");
    if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();const n=(i+(e.key==="ArrowDown"?1:-1)+its.length)%its.length;its.forEach((b,j)=>b.setAttribute("aria-selected",(j===n) as unknown as string));its[n].scrollIntoView({block:"nearest"})}else if(e.key==="Enter"){e.preventDefault();const [k,id]=(its[i]||its[0]).dataset.bigsk!.split("|");biGsOpen(k,id)}else if(e.key==="Escape"){box!.hidden=true}return}
  if(e.key==="Escape"){if(R.querySelector<HTMLInputElement>(".bi-dlg"))return;if(BI.ui.drawer){biDrawer(null);e.stopPropagation();return}if(BI.ui.navOpen){BI.ui.navOpen=false;R.querySelector<HTMLInputElement>(".bi-nav")!.classList.remove("open");R.querySelector<HTMLInputElement>(".bi-scrim")!.classList.remove("on");e.stopPropagation()}}
  if((e.key==="Enter"||e.key===" ")&&x.matches("tr[data-birow]")){e.preventDefault();const t=x.closest<HTMLInputElement>("[data-bitbl]")?.dataset.bitbl;BI_TBL[t!]?.open?.(x.dataset.birow!)}
  if((e.key==="ArrowDown"||e.key==="ArrowUp")&&x.matches("tr[data-birow]")){e.preventDefault();const n=(e.key==="ArrowDown"?x.nextElementSibling:x.previousElementSibling) as HTMLElement | null;n?.focus()}
  if(x.matches(".bi-ni,.bi-nh")&&(e.key==="ArrowDown"||e.key==="ArrowUp")){e.preventDefault();const all=[...R.querySelectorAll<HTMLInputElement>(".bi-nl .bi-ni,.bi-nl .bi-nh")].filter(b=>b.offsetParent);const i=all.indexOf(x);all[(i+(e.key==="ArrowDown"?1:-1)+all.length)%all.length]?.focus()}
  BI_P[BI.ui.view]?.key?.(e)},true);
