/* ===== v61 · Facturation & Revenus — dashboard, activity, revenue analytics, outstanding balances, allocation ===== */
/* ---------- charts (SVG, drawn to the container's width; validated colours: invoiced = blue, collected = orange) ---------- */
function biAxisNice(max: number){if(max<=0)return [1,0.25];const p=Math.pow(10,Math.floor(Math.log10(max)));const m=max/p;const top=(m<=1?1:m<=2?2:m<=2.5?2.5:m<=5?5:10)*p;return [top,top/4]}
function biShortM(v: number){const cur=biCur();const d=biCurD(cur);const u=v/10**d;const a=Math.abs(u);const s=a>=1e6?(u/1e6).toLocaleString(biLoc(),{maximumFractionDigits:1})+" M":a>=1e3?(u/1e3).toLocaleString(biLoc(),{maximumFractionDigits:1})+" k":u.toLocaleString(biLoc(),{maximumFractionDigits:0});return s+" "+BI_CUR[cur].s}
/* series: [{n, cls:"s0", v:[minor units], dash}], labels: [x labels], tips: [x long labels] */
function biLineChart(box: HTMLElement,labels: string[],series: BiSeries[],o: { h?: number; label?: string; tips?: string[] }={}){const W=Math.max(280,box.clientWidth),H=o.h||260,P={l:58,r:12,t:14,b:28};const iw=W-P.l-P.r,ih=H-P.t-P.b;const n=labels.length;const all=series.flatMap(s=>s.v);const [top,step]=biAxisNice(Math.max(1,...all));
  const X=(i: number)=>P.l+(n<=1?iw/2:i*iw/(n-1)),Y=(v: number)=>P.t+ih-(v/top)*ih;let g="";for(let v=0;v<=top+1e-9;v+=step){g+=`<line x1="${P.l}" x2="${W-P.r}" y1="${Y(v)}" y2="${Y(v)}" class="g"/><text x="${P.l-6}" y="${Y(v)+3}" text-anchor="end">${biE(biShortM(v))}</text>`}
  const every=Math.ceil(n/Math.max(2,Math.floor(iw/64)));labels.forEach((l,i)=>{if(i%every===0||i===n-1)g+=`<text x="${X(i)}" y="${H-8}" text-anchor="middle">${biE(l)}</text>`});
  const paths=series.map(s=>{const d=s.v.map((v,i)=>(i?"L":"M")+X(i).toFixed(1)+" "+Y(v).toFixed(1)).join("");const area=s.area?`<path d="${d}L${X(n-1)} ${Y(0)}L${X(0)} ${Y(0)}Z" class="ar ${s.cls}"/>`:"";return area+`<path d="${d}" class="ln ${s.cls}${s.dash?" dash":""}" pathLength="1"/>`+(n<=40&&!s.dash?s.v.map((v,i)=>`<circle cx="${X(i)}" cy="${Y(v)}" r="3.2" class="pt ${s.cls}"/>`).join(""):"")}).join("");
  box.innerHTML=`<svg class="bi-chart" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img" aria-label="${biE(o.label||"")}"><g class="grid">${g}</g>${paths}<line class="xh" x1="0" x2="0" y1="${P.t}" y2="${P.t+ih}" visibility="hidden"/><rect class="hit" x="${P.l}" y="${P.t}" width="${iw}" height="${ih}" fill="transparent"/></svg><div class="bi-ctip" hidden></div>`;
  const svg=box.querySelector<HTMLInputElement>("svg"),tip=box.querySelector<HTMLInputElement>(".bi-ctip"),xh=svg!.querySelector<HTMLInputElement>(".xh");
  if(!biRM())svg!.querySelectorAll<HTMLInputElement>(".ln").forEach((p,i)=>p.animate([{strokeDashoffset:1,strokeDasharray:"1 1"},{strokeDashoffset:0,strokeDasharray:"1 1"}],{duration:900,delay:i*120,easing:"cubic-bezier(.3,.7,.2,1)"}));
  const move=(e: PointerEvent)=>{const r=svg!.getBoundingClientRect();const x=(e.clientX-r.left)*W/r.width;const i=Math.max(0,Math.min(n-1,Math.round((x-P.l)/(n<=1?1:iw/(n-1)))));xh!.setAttribute("x1",(X(i)) as unknown as string);xh!.setAttribute("x2",(X(i)) as unknown as string);xh!.setAttribute("visibility","visible");
    tip!.innerHTML=`<b>${biE((o.tips||labels)[i])}</b>${series.map(s=>`<span><i class="${s.cls}${s.dash?" dash":""}"></i>${biE(s.n)} <b>${biE(biM(s.v[i]))}</b></span>`).join("")}`;tip!.hidden=false;const tx=X(i)*r.width/W;tip!.style.left=Math.min(r.width-tip!.offsetWidth-4,Math.max(4,tx+12))+"px";tip!.style.top="8px"};
  svg!.addEventListener("pointermove",move);svg!.addEventListener("pointerleave",()=>{tip!.hidden=true;xh!.setAttribute("visibility","hidden")})}
/* horizontal bars: rows [{l, v, v2?, go}] */
function biBarsHTML(rows: BiBar[],o: BiBarsOpts={}){const max=Math.max(1,...rows.map(r=>Math.max(r.v,r.v2||0)));return `<ul class="bi-bars">${rows.map((r,i)=>`<li style="--i:${i}"><button type="button" class="lbl"${r.go?` data-bigo="${r.go[0]}" data-biarg='${biE(JSON.stringify(r.go[1]))}'`:" disabled"}>${biE(r.l)}</button><div class="tr"><i class="b s0" style="--w:${(r.v/max*100).toFixed(2)}%"></i>${r.v2!==undefined?`<i class="b s1" style="--w:${(r.v2/max*100).toFixed(2)}%"></i>`:""}</div><span class="v">${biE(biM(r.v))}${r.v2!==undefined?`<small>${biE(biM(r.v2))}</small>`:""}</span></li>`).join("")}</ul>`}
const biLegend=(items: [string, string, (boolean | number)?][])=>`<div class="bi-legend">${items.map(([cls,l,dash])=>`<span><i class="${cls}${dash?" dash":""}"></i>${biE(l)}</span>`).join("")}</div>`;
const BI_INVD="Facturé (net des avoirs)|Invoiced (net of credit notes)|Fakturiert (netto Gutschriften)|المفوتر (صافي الإشعارات)",BI_CASH="Encaissé (net des remboursements)|Collected (net of refunds)|Eingenommen (netto Erstattungen)|المحصل (صافي الاستردادات)";

/* ---------- dashboard ---------- */
const BI_PK=[["day","Jour|Day|Tag|يوم"],["week","Semaine|Week|Woche|أسبوع"],["month","Mois|Month|Monat|شهر"],["quarter","Trimestre|Quarter|Quartal|ربع"],["year","Année|Year|Jahr|سنة"]];
function biDashRange(){const D=BI.ui.dash;const ref=D.ref||biToday();return biPeriod(D.per,ref)}
function biPerLabel(kind: string,[f,t]: string[]){const d=biD(f);if(kind==="day")return biFmtDate(f,{weekday:"long",day:"numeric",month:"long",year:"numeric"});if(kind==="month")return d.toLocaleDateString(biLoc(),{month:"long",year:"numeric"});if(kind==="year")return String(d.getFullYear());if(kind==="quarter")return "T"+(Math.floor(d.getMonth()/3)+1)+" "+d.getFullYear();return biFmtDate(f,{day:"numeric",month:"short"})+" – "+biFmtDate(t,{day:"numeric",month:"short",year:"numeric"})}
/* previous comparable period: when the current period is still running, compare the same number of elapsed days */
function biCmpPeriod(kind: string,R: string[]){const P=biPrevPeriod(kind,R);const t=biToday();if(R[1]>t&&R[0]<=t){const n=biDays(R[0],t);const end=biAddDays(P[0],n);return [P[0],end<P[1]?end:P[1]]}return P}
/* buckets for the evolution chart */
function biBuckets(kind: string,[f,t]: string[]){const out: string[][]=[];if(kind==="year"){for(let m=0;m<12;m++){const a=biAddMonths(f,m);const b=biAddDays(biAddMonths(a,1),-1);out.push([a,b,biD(a).toLocaleDateString(biLoc(),{month:"short"}),biD(a).toLocaleDateString(biLoc(),{month:"long",year:"numeric"})])}}
  else if(kind==="quarter"){let a=f;while(a<=t){const b=biAddDays(a,6)>t?t:biAddDays(a,6);out.push([a,b,biFmtDate(a,{day:"numeric",month:"short"}),biFmtDate(a,{day:"numeric",month:"short"})+" – "+biFmtDate(b,{day:"numeric",month:"short"})]);a=biAddDays(b,1)}}
  else{let a=kind==="day"?biAddDays(f,-13):f;const end=t;while(a<=end){out.push([a,a,kind==="week"?biD(a).toLocaleDateString(biLoc(),{weekday:"short"}):String(biD(a).getDate()),biFmtDate(a,{weekday:"long",day:"numeric",month:"long"})]);a=biAddDays(a,1)}}return out}
function biDashFlt(){const f=BI.ui.dash.flt;const o: Dict={};if(f.prac)o.prac=f.prac;if(f.est)o.est=f.est;if(f.payer)o.payer=f.payer;if(f.cat)o.cat=f.cat;return o}
function biDashHTML(){const D=BI.ui.dash;const R=biDashRange();const P=biCmpPeriod(D.per,R);const flt=biDashFlt();const F=biFacts(R[0],R[1],flt),FP=biFacts(P[0],P[1],flt);const S=BI.st;
  const inv=biSum(F,["inv","cn"]),invP=biSum(FP,["inv","cn"]),cash=biSum(F,["cash","refund"]),cashP=biSum(FP,["cash","refund"]);const rec=biReceivable(R[1]>biToday()?biToday():R[1],flt);
  const nInv=F.filter(x=>x.k==="inv").length,nInvP=FP.filter(x=>x.k==="inv").length;const avg=nInv?biDivRound(biSum(F,"inv"),nInv):0,avgP=nInvP?biDivRound(biSum(FP,"inv"),nInvP):0;const cnr=-biSum(F,["cn"])-biSum(F,["refund"]);const cnrP=-biSum(FP,["cn"])-biSum(FP,["refund"]);
  const unrec=S!.payments.filter(p=>p.status==="ok"&&p.recon==="unmatched").length+S!.bank.filter(b=>!b.match).length;const overdueN=S!.invoices.filter(i=>biScope(i)&&biOverdue(i)&&Object.entries(flt).every(([k,v])=>biDims(i)[k]===v)).length;
  const dlt=(a: number,b: number)=>{if(!b)return a?`<span class="bi-dl n">${biE(L4("nouveau|new|neu|جديد"))}</span>`:`<span class="bi-dl n">—</span>`;const p=Math.round((a-b)*1000/Math.abs(b))/10;return `<span class="bi-dl ${p>0?"up":p<0?"dn":"n"}">${bii(p>=0?"trend":"trendDown",13)}${p>0?"+":""}${p.toLocaleString(biLoc(),{maximumFractionDigits:1})} %</span>`};
  const perArg={per:"custom",from:R[0],to:R[1]};
  const K: [string, string, number, string, string, [string, unknown], string, string?][]=[["inv","CA facturé|Invoiced revenue|Fakturierter Umsatz|الإيرادات المفوترة",inv,dlt(inv,invP),"Factures émises sur la période, TTC, moins les avoirs de la période.|Invoices issued in the period, incl. tax, minus credit notes of the period.|Ausgestellte Rechnungen abzüglich Gutschriften.|الفواتير الصادرة ناقص الإشعارات.",["invoices",Object.assign({},perArg)],"file"],
   ["cash","Revenus encaissés|Cash collected|Zahlungseingänge|الإيرادات المحصلة",cash,dlt(cash,cashP),"Paiements reçus (statut encaissé) datés dans la période, moins les remboursements effectués.|Payments received (status received) dated in the period, minus completed refunds.|Eingegangene Zahlungen abzüglich Erstattungen.|المدفوعات المستلمة ناقص الاستردادات.",["transactions",Object.assign({},perArg)],"coin"],
   ["rec","Restant à encaisser|Outstanding receivables|Offene Forderungen|المستحقات",rec.tot,`<span class="bi-dl n">${biNf(rec.n)} ${biE(L4("factures|invoices|Rechnungen|فواتير"))}</span>`,"Soldes des factures émises au "+biFmtDate(R[1]>biToday()?biToday():R[1])+" (montant − avoirs − paiements).|Balances of issued invoices at the period end (amount − credits − payments).|Offene Salden zum Periodenende.|أرصدة الفواتير في نهاية الفترة.",["outstanding",{}],"wallet"],
   ["late","Factures en retard|Overdue invoices|Überfällige Rechnungen|فواتير متأخرة",rec.over,`<span class="bi-dl ${rec.no?"dn":"n"}">${biNf(overdueN)} ${biE(L4("aujourd’hui|today|heute|اليوم"))}</span>`,"Part du restant dû dont l’échéance est dépassée en fin de période.|Part of receivables past their due date at period end.|Teil der Forderungen nach Fälligkeit.|الجزء المتجاوز للاستحقاق.",["invoices",{st:"overdue"}],"alert"],
   ["recon","Paiements à rapprocher|Payments to reconcile|Abzugleichende Zahlungen|مدفوعات للمطابقة",unrec,`<span class="bi-dl n">${biE(L4("toutes périodes|all periods|alle Zeiträume|كل الفترات"))}</span>`,"Paiements non rapprochés et lignes de relevé bancaire sans correspondance.|Unmatched payments and bank lines without a match.|Nicht abgeglichene Zahlungen und Bankzeilen.|مدفوعات وأسطر غير مطابقة.",["recon",{}],"scale","n"],
   ["cnr","Avoirs et remboursements|Credit notes and refunds|Gutschriften und Erstattungen|الإشعارات والاستردادات",cnr,dlt(cnr,cnrP),"Avoirs émis + remboursements effectués dans la période.|Credit notes issued + refunds completed in the period.|Gutschriften + Erstattungen.|الإشعارات + الاستردادات.",["credits",Object.assign({},perArg)],"undo"],
   ["avg","Facture moyenne|Average invoice|Durchschnittsrechnung|متوسط الفاتورة",avg,dlt(avg,avgP),"Total des factures émises ÷ nombre de factures émises (hors avoirs).|Total of issued invoices ÷ number of invoices (credit notes excluded).|Summe ÷ Anzahl.|المجموع ÷ العدد.",["invoices",Object.assign({},perArg)],"receipt"],
   ["evo","Évolution du facturé|Invoiced revenue change|Umsatzentwicklung|تطور المفوتر",inv-invP,dlt(inv,invP),"CA facturé de la période − celui de la période précédente comparable ("+biFmtDate(P[0])+" → "+biFmtDate(P[1])+", même nombre de jours écoulés).|Invoiced revenue minus the previous comparable period (same number of elapsed days).|Differenz zur Vorperiode (gleiche Tage).|الفرق مع الفترة السابقة.",["reports",{}],"trend"]];
  const cats=Object.keys(BI_CATS).filter(c=>S!.services.some(s=>s.cat===c));
  return `<div class="bi-dbar"><div class="bi-seg" role="radiogroup" aria-label="${biE(biW("period"))}">${BI_PK.map(([k,l])=>`<button type="button" role="radio" aria-checked="${D.per===k}" data-biper="${k}">${biE(L4(l))}</button>`).join("")}</div>
     <div class="bi-pnav"><button type="button" class="bi-ib" data-bipnav="-1" aria-label="${biE(biW("prev"))}">${bii("back")}</button><b>${biE(biPerLabel(D.per,R))}</b><button type="button" class="bi-ib" data-bipnav="1" aria-label="${biE(biW("next"))}"${R[1]>=biToday()?" disabled":""}>${bii("chev")}</button>${D.ref?`<button type="button" class="bi-btn sm ghost" data-bipnav="0">${biE(L4("Aujourd’hui|Today|Heute|اليوم"))}</button>`:""}</div><span class="sp"></span>
     ${biRole()!=="prac"?`<select class="bi-in sm" data-bidf="prac" aria-label="${biE(biW("prac"))}">${biOpts(biPracOpts(),D.flt.prac,{any:biW("prac")+" : "+biW("any")})}</select>`:""}<select class="bi-in sm" data-bidf="est" aria-label="${biE(biW("est"))}">${biOpts(biEstOpts(),D.flt.est,{any:biW("est")+" : "+biW("any")})}</select><select class="bi-in sm" data-bidf="cat" aria-label="${biE(L4("Catégorie|Category|Kategorie|الفئة"))}">${biOpts(cats.map(c=>[c,L4(BI_CATS[c])]),D.flt.cat,{any:L4("Catégorie|Category|Kategorie|الفئة")+" : "+biW("any")})}</select><select class="bi-in sm" data-bidf="payer" aria-label="${biE(biW("payer"))}">${biOpts(biPayerOpts(),D.flt.payer,{any:biW("payer")+" : "+biW("any")})}</select></div>
   ${biRole()==="prac"?`<p class="bi-note">${bii("lock",14)}${biE(L4("Vue praticien : seules vos factures et leurs encaissements sont comptés.|Practitioner view: only your invoices and their payments are counted.|Behandleransicht: nur eigene Rechnungen.|عرض الممارس: فواتيرك فقط."))} (${biE(biPracName(biMe()))})</p>`:""}
   <div class="bi-kpis">${K.map(([k,l,v,d,def,go,ic,kind])=>`<button type="button" class="bi-kpi" data-bigo="${go[0]}" data-biarg='${biE(JSON.stringify(go[1]))}'><span class="t">${bii(ic,15)}${biE(L4(l))}</span><b class="v" data-bicu="${v}" data-kind="${kind||"m"}">${biE(kind==="n"?biNf(v):biM(v))}</b>${d}<small>${biE(L4(def))}</small></button>`).join("")}</div>
   <div class="bi-dgrid"><section class="bi-card bi-evo"><header><h3>${bii("chart",16)}${biE(L4("Évolution des revenus|Revenue evolution|Umsatzentwicklung|تطور الإيرادات"))}</h3>${biLegend([["s0",L4(BI_INVD)],["s1",L4(BI_CASH)],["s0",L4("Facturé, période précédente|Invoiced, previous period|Fakturiert, Vorperiode|المفوتر، الفترة السابقة"),1]])}</header><div class="bi-chartw" data-bievo></div><p class="bi-mut sm">${biE(L4("Remboursements, annulations et avoirs sont déduits à leur propre date ; un paiement partiel compte pour son seul montant reçu.|Refunds, cancellations and credit notes are deducted at their own date; a partial payment counts only for the amount received.|Erstattungen und Gutschriften werden zum eigenen Datum abgezogen.|تُخصم الاستردادات والإشعارات بتاريخها."))}</p></section>
    <section class="bi-card bi-brk"><header><h3>${bii("layers",16)}${biE(L4("Répartition|Breakdown|Aufteilung|التوزيع"))}</h3><div class="bi-seg sm">${[["prac",BIW.prac],["cat","Catégorie|Category|Kategorie|الفئة"],["est",BIW.est],["method","Moyen de paiement|Payment method|Zahlungsart|وسيلة الدفع"],["payer",BIW.payer]].filter(([k])=>!(k==="prac"&&biRole()==="prac")).map(([k,l])=>`<button type="button" aria-pressed="${(D.brk||"prac")===k}" data-bibrk="${k}">${biE(L4(l))}</button>`).join("")}</div></header>${biLegend([["s0",L4(BI_INVD)],["s1",L4(BI_CASH)]])}<div data-bibrkb>${biBrkHTML(F,D.brk||"prac")}</div></section>
    <section class="bi-card bi-out"><header><h3>${bii("wallet",16)}${biE(L4("Factures à encaisser|Outstanding invoices|Offene Rechnungen|فواتير مستحقة"))}</h3><button type="button" class="bi-btn sm" data-bigo="outstanding">${biE(L4("Tout voir|See all|Alle|عرض الكل"))}${bii("chev",13)}</button></header>${biOutMini(flt)}</section>
    <section class="bi-card bi-act"><header><h3>${bii("pulse",16)}${biE(L4("Activité financière récente|Recent financial activity|Letzte Aktivitäten|النشاط المالي الأخير"))}</h3><button type="button" class="bi-btn sm" data-bigo="activity">${biE(L4("Tout voir|See all|Alle|عرض الكل"))}${bii("chev",13)}</button></header>${biFeedHTML(biFeed().slice(0,9))}</section></div>`}
function biBrkHTML(F: BiFact[],dim: string){const by: Record<string, { v: number; v2: number }>={};F.forEach(x=>{if(x.unapplied&&dim!=="method")return;const k=dim==="method"?x.dims.method:x.dims[dim];if(!k)return;if(dim==="method"&&x.k!=="cash"&&x.k!=="refund")return;const o=(by[k]=by[k]||{v:0,v2:0});if(x.k==="inv"||x.k==="cn")o.v+=x.amt;else o.v2+=x.amt});
  const name=(k: string)=>dim==="prac"?biPracName(k):dim==="est"?biEstName(k):dim==="cat"?L4(BI_CATS[k]||k):dim==="payer"?(BI.st!.payers.find(p=>p.id===k)?.name||k):L4((BI_METHODS.find(m=>m[0]===k)||[0,k])[1]);
  const rows=Object.entries(by).filter(([k])=>k!=="-").map(([k,o])=>({l:name(k),v:dim==="method"?o.v2:o.v,v2:dim==="method"?undefined:o.v2,go:(dim==="method"?["transactions",{method:k}]:["invoices",dim==="cat"?{}:{[dim]:k}]) as [string, unknown]})).sort((a,b)=>b.v-a.v).slice(0,8);
  return rows.length?biBarsHTML(rows):biEmpty("chart",biW("empty"))}
function biOutMini(flt: Dict){const rows=BI.st!.invoices.filter(i=>biScope(i)&&i.status==="issued"&&biBal(i)>0&&Object.entries(flt).every(([k,v])=>biDims(i)[k]===v)).sort((a,b)=>biDaysLate(b)-biDaysLate(a)||(a.due!<b.due!?-1:1)).slice(0,7);
  return rows.length?`<div class="bi-tbs"><table class="bi-tb bi-tbm"><thead><tr><th>${biE(biW("party"))}</th><th>${biE(L4("Facture|Invoice|Rechnung|الفاتورة"))}</th><th>${biE(biW("due"))}</th><th class="num">${biE(biW("total"))}</th><th class="num">${biE(biW("paid"))}</th><th class="num">${biE(biW("balance"))}</th><th>${biE(biW("status"))}</th></tr></thead><tbody>${rows.map(i=>`<tr data-bidrw="inv|${i.id}" tabindex="0"><td>${biE(biPartyName(i.party))}</td><td class="bi-mono">${biE(i.no)}<small>${biE(biFmtDate(i.issue))}</small></td><td>${biE(biFmtDate(i.due))}${biDaysLate(i)?`<small class="bi-late">+${biNf(biDaysLate(i))} j</small>`:""}</td><td class="num">${biE(biM(biDocTotal(i)))}</td><td class="num">${biE(biM(biPaid(i)))}</td><td class="num"><b class="bi-bal">${biE(biM(biBal(i)))}</b></td><td>${biSt8(biInvState(i))}</td></tr>`).join("")}</tbody></table></div>`:biEmpty("check",L4("Aucune facture en attente de paiement.|No invoice awaiting payment.|Keine offenen Rechnungen.|لا فواتير مستحقة."))}
/* activity built from the documents themselves (dates of issue, payment, credit, refund) */
function biFeed(){const S=BI.st;const out: BiFeedItem[]=[];S!.invoices.forEach(i=>{if(!biScope(i))return;if(i.status==="issued")out.push({d:i.issuedAt&&i.issuedAt.slice(0,10)>i.issue?i.issuedAt.slice(0,10):i.issue,ts:i.issuedAt||i.issue,k:"inv",ic:"file",t:L4("Facture émise|Invoice issued|Rechnung ausgestellt|صدرت فاتورة"),s:i.no+" · "+biPartyName(i.party),v:biDocTotal(i),go:["inv",i.id]});else out.push({d:(i.created||"").slice(0,10),ts:i.created,k:"draft",ic:"inbox",t:L4("Brouillon créé|Draft created|Entwurf erstellt|أنشئت مسودة"),s:biPartyName(i.party),v:biTotals(i).total,go:["edit",i.id]});if(i.corrects)out.push({d:(i.created||"").slice(0,10),ts:i.created,k:"corr",ic:"undo",t:L4("Correction de facture|Invoice corrected|Rechnung korrigiert|تصحيح فاتورة"),s:biInv(i.corrects)?.no||"",v:null,go:["inv",i.corrects]})});
  S!.payments.forEach(p=>{const part=p.alloc.some(a=>{const inv=biInv(a.inv);return inv&&biPayState(inv)==="partial"});if(p.alloc.some(a=>!biScope(biInv(a.inv)||{})))return;out.push({d:p.date,ts:p.at||p.date,k:p.status!=="ok"?"payx":part?"part":"pay",ic:p.status!=="ok"?"alert":part?"half":"coin",t:p.status!=="ok"?L4("Paiement échoué ou rejeté|Payment failed or reversed|Zahlung fehlgeschlagen|فشل الدفع"):part?L4("Paiement partiel enregistré|Partial payment recorded|Teilzahlung erfasst|دفعة جزئية"):L4("Paiement reçu|Payment received|Zahlung erhalten|دفعة مستلمة"),s:p.no+" · "+biPartyName(p.party),v:p.amount,go:["pay",p.id]})});
  S!.credits.forEach(c=>{if(!biScope(c))return;out.push({d:c.issue,ts:c.issue,k:"cn",ic:"credit",t:L4("Avoir créé|Credit note created|Gutschrift erstellt|أنشئ إشعار دائن"),s:c.no+" → "+(biInv(c.inv)?.no||""),v:-c.snap!.tot.total,go:["cn",c.id]})});
  if(biRole()!=="prac")S!.refunds.forEach(r=>out.push({d:r.date,ts:r.date,k:"rf",ic:"undo",t:r.status==="done"?L4("Remboursement effectué|Refund completed|Erstattung erledigt|استرداد منجز"):L4("Remboursement à effectuer|Refund pending|Erstattung ausstehend|استرداد معلق"),s:r.no+" · "+biPartyName(r.party),v:-r.amount,go:["rf",r.id]}));
  return out.sort((a,b)=>a.d<b.d?1:a.d>b.d?-1:String(a.ts)<String(b.ts)?1:-1)}
function biFeedHTML(items: BiFeedItem[]){return items.length?`<ol class="bi-feed">${items.map((x,i)=>`<li style="--i:${i}" class="k-${x.k}"><span class="ic">${bii(x.ic,14)}</span><button type="button" data-bifeed="${x.go[0]}|${x.go[1]}"><b>${biE(x.t)}</b><small>${biE(x.s)}</small></button><span class="r">${x.v!==null?`<b>${biE(biM(x.v))}</b>`:""}<small>${biE(biFmtDate(x.d,{day:"numeric",month:"short"}))}</small></span></li>`).join("")}</ol>`:biEmpty("pulse",biW("empty"))}
function biDashMount(R: HTMLElement){const box=R.querySelector<HTMLInputElement>("[data-bievo]");if(!box)return;const D=BI.ui.dash;const rg=biDashRange();const prev=biPrevPeriod(D.per,rg);const B=biBuckets(D.per,rg);const BP=biBuckets(D.per,prev);const flt=biDashFlt();
  const sum=(bk: string[][],ks: string[])=>bk.map(([a,b])=>biSum(biFacts(a,b,flt),ks));const draw=()=>biLineChart(box,B.map(b=>b[2]),[{n:L4(BI_INVD),cls:"s0",v:sum(B,["inv","cn"]),area:true},{n:L4(BI_CASH),cls:"s1",v:sum(B,["cash","refund"])},{n:L4("Facturé, période précédente|Invoiced, previous period|Vorperiode|الفترة السابقة"),cls:"s0",dash:true,v:sum(BP.slice(0,B.length),["inv","cn"]).concat(Array(Math.max(0,B.length-BP.length)).fill(0))}],{tips:B.map(b=>b[3]),label:L4("Évolution des revenus|Revenue evolution|Umsatzentwicklung|تطور الإيرادات")});
  draw();try{let w=box.clientWidth;const ro=new ResizeObserver(()=>{if(Math.abs(box.clientWidth-w)>8){w=box.clientWidth;draw()}});ro.observe(box)}catch(e){}}
biDef("dash","ov",{n:"Tableau de bord|Dashboard|Dashboard|لوحة القيادة",ic:"grid",perm:"dash",title:()=>L4("Facturation & Revenus|Billing & Revenue|Abrechnung & Umsatz|الفوترة والإيرادات"),page:biDashHTML,mount:biDashMount,
 click:(e,c)=>{let x: HTMLInputElement | null;const D=BI.ui.dash;if((x=c("[data-biper]"))){D.per=x.dataset.biper!;D.ref=null;biRefresh();return}if((x=c("[data-bipnav]"))){const d=+x.dataset.bipnav!;if(!d)D.ref=null;else{const [f,t]=biDashRange();D.ref=d<0?biAddDays(f,-1):biAddDays(t,1);if(D.ref>=biToday())D.ref=null}biRefresh();return}
  if((x=c("[data-bibrk]"))){D.brk=x.dataset.bibrk;const R=biRoot();R!.querySelectorAll<HTMLInputElement>("[data-bibrk]").forEach(b=>b.setAttribute("aria-pressed",(b===x) as unknown as string));const rg=biDashRange();R!.querySelector<HTMLInputElement>("[data-bibrkb]")!.innerHTML=biBrkHTML(biFacts(rg[0],rg[1],biDashFlt()),D.brk!);return}
  if((x=c("[data-bifeed]"))){biFeedGo(x.dataset.bifeed!);return}},
 change:e=>{const x=tgt(e);if(x.matches("[data-bidf]")){BI.ui.dash.flt[x.dataset.bidf!]=x.value;biRefresh();biRoot()!.querySelector<HTMLInputElement>(`[data-bidf="${x.dataset.bidf}"]`)?.focus()}}});
function biFeedGo(s: string){const [k,id]=s.split("|");if(k==="inv")biDrawer("inv",id);else if(k==="edit")biGo("editor",id);else if(k==="cn")biDrawer("cn",id);else if(k==="pay")biDrawer("pay",id);else if(k==="rf"){biGo("refunds")}}

/* ---------- activity ---------- */
biDef("activity","ov",{n:"Activité financière|Financial activity|Finanzaktivität|النشاط المالي",ic:"pulse",perm:"dash",page:()=>{const f=biFlt("activity");const [pf,pt]=biPerRange(f);const ty=f.ty||"";const items=biFeed().filter(x=>biInRange(x.d,pf,pt)&&(!ty||x.k===ty)&&(!f.q||(x.t+" "+x.s).toLowerCase().includes(f.q.toLowerCase())));const shown=items.slice(0,BI.ui.actN||60);
  const types=[["inv","Factures émises|Invoices issued|Rechnungen|فواتير"],["pay","Paiements reçus|Payments received|Zahlungen|مدفوعات"],["part","Paiements partiels|Partial payments|Teilzahlungen|جزئية"],["payx","Paiements échoués|Failed payments|Fehlgeschlagen|فاشلة"],["cn","Avoirs|Credit notes|Gutschriften|إشعارات"],["rf","Remboursements|Refunds|Erstattungen|استردادات"],["corr","Corrections|Corrections|Korrekturen|تصحيحات"],["draft","Brouillons|Drafts|Entwürfe|مسودات"]];
  return `${biFltHTML("activity",f,{prac:false,est:false})}<div class="bi-chips">${[["",biW("all")],...types.map(([k,l])=>[k,L4(l)])].map(([k,l])=>`<button type="button" class="bi-chip" aria-pressed="${ty===k}" data-bity="${k}">${biE(l)}</button>`).join("")}</div><section class="bi-card">${biFeedHTML(shown)}${items.length>shown.length?`<div class="bi-acts center"><button type="button" class="bi-btn" data-bimore>${biE(L4("Afficher plus|Show more|Mehr anzeigen|عرض المزيد"))} (${biNf(items.length-shown.length)})</button></div>`:""}</section>`},
 click:(e,c)=>{let x: HTMLInputElement | null;if((x=c("[data-bity]"))){biFlt("activity").ty=x.dataset.bity;BI.ui.actN=60;biRefresh();return}if(c("[data-bimore]")){BI.ui.actN=(BI.ui.actN||60)+60;biRefresh();return}if((x=c("[data-bifeed]")))biFeedGo(x.dataset.bifeed!)}});

/* ---------- revenue reports ---------- */
const BI_FORMULAS=[["Facturé brut|Gross invoiced|Brutto fakturiert|المفوتر الإجمالي","Σ total TTC des factures émises, datées à la date d’émission|Σ incl.-tax total of issued invoices, by issue date|Σ Rechnungsbeträge nach Ausstellungsdatum|مجموع الفواتير الصادرة"],["Avoirs|Credit notes|Gutschriften|الإشعارات","Σ avoirs émis, datés à leur propre date|Σ credit notes, by their own date|Σ Gutschriften nach eigenem Datum|مجموع الإشعارات"],["Facturé net|Net invoiced|Netto fakturiert|المفوتر الصافي","Facturé brut − avoirs|Gross invoiced − credit notes|Brutto − Gutschriften|الإجمالي − الإشعارات"],
 ["Encaissé|Cash received|Zahlungseingang|المحصل","Σ paiements au statut « encaissé », datés au jour du paiement (échoués et rejetés exclus)|Σ payments with status received, by payment date (failed/reversed excluded)|Σ eingegangene Zahlungen|مجموع المدفوعات المستلمة"],["Remboursements|Refunds|Erstattungen|الاستردادات","Σ remboursements effectués, datés à leur exécution|Σ completed refunds, by completion date|Σ erledigte Erstattungen|مجموع الاستردادات"],["Encaissé net|Net cash|Netto-Eingang|المحصل الصافي","Encaissé − remboursements|Cash received − refunds|Eingang − Erstattungen|المحصل − الاستردادات"],
 ["Créances|Receivables|Forderungen|المستحقات","Σ (total − avoirs − paiements) des factures émises, à la date de fin|Σ (total − credits − payments) of issued invoices at the end date|Offene Salden zum Stichtag|الأرصدة في تاريخ النهاية"],["En retard|Overdue|Überfällig|متأخر","Part des créances dont l’échéance est passée à la date de fin|Receivables past due at the end date|Überfällige Forderungen|المستحقات المتأخرة"]];
function biRepRow(f: string,t: string){const F=biFacts(f,t);const gross=biSum(F,"inv"),cn=-biSum(F,"cn"),cash=biSum(F,"cash"),rf=-biSum(F,"refund");const r=biReceivable(t>biToday()?biToday():t);return {gross,cn,net:gross-cn,cash,rf,ncash:cash-rf,rec:r.tot,over:r.over,n:F.filter(x=>x.k==="inv").length}}
biDef("reports","ov",{n:"Rapports de revenus|Revenue reports|Umsatzberichte|تقارير الإيرادات",ic:"chart",perm:["rep.all","rep.own"],page:()=>{const t=biToday();const m=biPeriod("month",t);const pm=biPrevPeriod("month",m);const ym: [string, string]=[biAddMonths(m[0],-12),biAddDays(biAddMonths(m[0],-11),-1)];const ytd: [string, string]=[biPeriod("year",t)[0],t];const pytd: [string, string]=[biAddMonths(ytd[0],-12),biAddMonths(t,-12)];
  const C=[["m",L4("Mois en cours|This month|Dieser Monat|هذا الشهر"),biRepRow(...m)],["pm",L4("Mois précédent|Previous month|Vormonat|الشهر السابق"),biRepRow(...pm)],["ym",L4("Même mois N−1|Same month last year|Vorjahresmonat|نفس الشهر العام الماضي"),biRepRow(...ym)],["ytd",L4("Année à date|Year to date|Jahr bis heute|منذ بداية العام"),biRepRow(...ytd)],["pytd",L4("Année N−1 à date|Last year to date|Vorjahr bis heute|العام الماضي حتى التاريخ"),biRepRow(...pytd)]];
  const lines=[["gross",BI_FORMULAS[0][0]],["cn",BI_FORMULAS[1][0]],["net",BI_FORMULAS[2][0]],["cash",BI_FORMULAS[3][0]],["rf",BI_FORMULAS[4][0]],["ncash",BI_FORMULAS[5][0]],["rec",BI_FORMULAS[6][0]],["over",BI_FORMULAS[7][0]],["n","Nombre de factures|Number of invoices|Anzahl Rechnungen|عدد الفواتير"]];
  const pc=(a: number,b: number)=>!b?"—":((a-b)*100/Math.abs(b)).toLocaleString(biLoc(),{maximumFractionDigits:1,signDisplay:"always"})+" %";
  const months: [string, string][]=[];for(let i=11;i>=0;i--){const a=biAddMonths(m[0],-i);const b=biAddDays(biAddMonths(a,1),-1);months.push([a,b>t?t:b])}const MR=months.map(([a,b])=>Object.assign({a},biRepRow(a,b)));BI.ui.repMonths=MR;
  return `<p class="bi-desc">${biE(L4("Le facturé, l’encaissé, les avoirs, les remboursements et les créances sont des notions distinctes : aucune n’est un bénéfice comptable, et les charges ne sont pas suivies ici.|Invoiced, collected, credit notes, refunds and receivables are distinct concepts: none of them is accounting profit, and expenses are not tracked here.|Fakturiert, Eingang, Gutschriften und Forderungen sind verschieden; keiner davon ist Gewinn.|المفوتر والمحصل والإشعارات مفاهيم مختلفة وليست ربحًا."))}</p>
   <section class="bi-card"><header class="bi-ch"><h3>${bii("chart",16)}${biE(L4("Comparaisons|Comparisons|Vergleiche|المقارنات"))}</h3><button type="button" class="bi-btn sm" data-birepcsv="cmp">${bii("dl",14)}${biE(biW("export"))}</button></header><div class="bi-tbs"><table class="bi-tb"><thead><tr><th></th>${C.map(c=>`<th class="num">${biE(c[1])}</th>`).join("")}<th class="num">${biE(L4("M / M−1|MoM|MoM|شهري"))}</th><th class="num">${biE(L4("A / A−1|YoY|YoY|سنوي"))}</th></tr></thead><tbody>${lines.map(([k,l])=>`<tr><th>${biE(L4(l))}</th>${C.map(c=>`<td class="num">${biE(k==="n"?biNf((c[2] as Num)[k]):biM((c[2] as Num)[k]))}</td>`).join("")}<td class="num">${biE(pc((C[0][2] as Num)[k],(C[1][2] as Num)[k]))}</td><td class="num">${biE(pc((C[3][2] as Num)[k],(C[4][2] as Num)[k]))}</td></tr>`).join("")}</tbody></table></div><p class="bi-mut sm">${biE(L4("Le mois en cours et l’année à date sont comparés aux mêmes dates de la période de référence lorsque c’est possible (année N−1 à date) ; M/M−1 compare un mois partiel à un mois complet.|Year to date is compared with the same dates last year; MoM compares a partial month with a full month.|YTD mit gleichen Vorjahresdaten; MoM vergleicht Teil- mit Vollmonat.|المقارنة الشهرية تقارن شهرًا جزئيًا بشهر كامل."))}</p></section>
   <section class="bi-card"><header class="bi-ch"><h3>${bii("cal",16)}${biE(L4("12 derniers mois|Last 12 months|Letzte 12 Monate|آخر 12 شهرًا"))}</h3>${biLegend([["s0",L4(BI_INVD)],["s1",L4(BI_CASH)]])}<button type="button" class="bi-btn sm" data-birepcsv="months">${bii("dl",14)}${biE(biW("export"))}</button></header><div class="bi-chartw" data-birep12></div>
    <div class="bi-tbs"><table class="bi-tb"><thead><tr><th>${biE(L4("Mois|Month|Monat|الشهر"))}</th>${lines.filter(l=>!["rec","over"].includes(l[0])).map(([k,l])=>`<th class="num">${biE(L4(l))}</th>`).join("")}</tr></thead><tbody>${MR.slice().reverse().map(r=>`<tr><th>${biE(biD(r.a).toLocaleDateString(biLoc(),{month:"long",year:"numeric"}))}</th>${lines.filter(l=>!["rec","over"].includes(l[0])).map(([k])=>`<td class="num">${biE(k==="n"?biNf((r as unknown as Num)[k]):biM((r as unknown as Num)[k]))}</td>`).join("")}</tr>`).join("")}</tbody></table></div></section>
   <section class="bi-card"><h3>${bii("info",16)}${biE(L4("Définitions et formules|Definitions and formulas|Definitionen und Formeln|التعريفات والصيغ"))}</h3><dl class="bi-defs">${BI_FORMULAS.map(([l,d])=>`<div><dt>${biE(L4(l))}</dt><dd>${biE(L4(d))}</dd></div>`).join("")}</dl></section>`},
 mount:R=>{const box=R.querySelector<HTMLInputElement>("[data-birep12]");const MR=BI.ui.repMonths;if(box&&MR)biLineChart(box,MR.map(r=>biD(r.a).toLocaleDateString(biLoc(),{month:"short"})),[{n:L4(BI_INVD),cls:"s0",v:MR.map(r=>r.net),area:true},{n:L4(BI_CASH),cls:"s1",v:MR.map(r=>r.ncash)}],{tips:MR.map(r=>biD(r.a).toLocaleDateString(biLoc(),{month:"long",year:"numeric"})),h:240})},
 click:(e,c)=>{let x: HTMLInputElement | null;if((x=c("[data-birepcsv]"))){const MR=BI.ui.repMonths;biDownload(`revenus-12-mois-${biToday()}.csv`,biCsv(["Mois","Facturé brut","Avoirs","Facturé net","Encaissé","Remboursements","Encaissé net","Factures"],MR!.map(r=>[r.a.slice(0,7),...["gross","cn","net","cash","rf","ncash"].map(k=>biM((r as unknown as Num)[k],null,{plain:true})),r.n])))}}});

/* ---------- revenue by dimension ---------- */
function biRevPage(dim: string,key: string){const f=biFlt(key);if(!f.per)f.per="year";const [pf,pt]=biPerRange(f);const F=biFacts(pf||"0000",pt||"9999");const by: Record<string, { n: number; inv: number; cash: number }>={};const nm=(k: string)=>dim==="prac"?biPracName(k):dim==="est"?biEstName(k):dim==="svc"?L4(biSvc(k)?.n||k):dim==="payer"?(BI.st!.payers.find(p=>p.id===k)?.name||k):L4((BI_METHODS.find(m=>m[0]===k)||[0,k])[1]);
  F.forEach(x=>{if(x.unapplied||x.k==="refund")return;let ks: (string | null | undefined)[] | null=[x.dims[dim]];if(dim==="svc"&&(x.k==="inv")){ks=null;x.lines!.forEach(l=>{const o=(by[l.svc||"-"]=by[l.svc||"-"]||{n:0,inv:0,cash:0});o.inv+=(l.c?l.c.total:biLine(l).total);o.n++})}if(!ks)return;ks.forEach(k=>{const o=(by[k!]=by[k!]||{n:0,inv:0,cash:0});if(x.k==="inv"){if(dim!=="svc")o.inv+=x.amt;if(dim!=="svc")o.n++}else if(x.k==="cn"){o.inv+=x.amt}else if(x.k==="cash")o.cash+=x.amt})});
  const totInv=Object.values(by).reduce((s,o)=>s+o.inv,0);const rows=Object.entries(by).filter(([k])=>k&&k!=="-"&&k!=="undefined").map(([k,o])=>({id:k,name:nm(k),n:o.n,inv:o.inv,cash:o.cash,share:totInv?Math.round(o.inv*10000/totInv):0}));
  const cols: BiCol<(typeof rows)[number]>[]=[{k:"name",l:{prac:BIW.prac,est:BIW.est,svc:"Prestation|Service|Leistung|الخدمة",payer:BIW.payer,method:BIW.method}[dim]!,v:r=>r.name,h:r=>`<b>${biE(r.name)}</b>`},{k:"n",l:dim==="svc"?"Lignes facturées|Lines invoiced|Positionen|أسطر":"Factures|Invoices|Rechnungen|الفواتير",num:true,v:r=>r.n,h:r=>biE(biNf(r.n))},{k:"inv",l:BI_INVD,num:true,v:r=>r.inv,h:r=>biE(biM(r.inv))},...(dim==="svc"?[]:[{k:"cash",l:BI_CASH,num:true,v:(r: (typeof rows)[number])=>r.cash,h:(r: (typeof rows)[number])=>biE(biM(r.cash))}]),{k:"share",l:"Part du facturé|Share of invoiced|Anteil|الحصة",num:true,v:r=>r.share,h:r=>`<span class="bi-share"><i style="--w:${r.share/100}%"></i>${biE(biPct(r.share))}</span>`}];BI_TBL[key]={cols,rows};
  return `<p class="bi-desc">${biE(L4(dim==="svc"?"Montants TTC par ligne de prestation, factures émises sur la période ; les avoirs globaux ne sont pas ventilés par prestation.|Incl.-tax amounts per service line on invoices issued in the period; credit notes are not split by service.|Beträge je Leistungsposition; Gutschriften nicht aufgeteilt.|المبالغ لكل سطر خدمة.":"Facturé net des avoirs par date d’émission ; encaissé par date de paiement, affecté via les factures réglées.|Invoiced net of credit notes by issue date; collected by payment date, attributed through the invoices paid.|Fakturiert netto nach Ausstellung; Eingang nach Zahlungsdatum.|المفوتر حسب تاريخ الإصدار والمحصل حسب تاريخ الدفع."))}</p>${biFltHTML(key,f,{prac:false,est:false})}<div class="bi-two"><section class="bi-card">${biLegend([["s0",L4(BI_INVD)],...((dim==="svc"?[]:[["s1",L4(BI_CASH)]]) as [string, string][])])}${biBarsHTML(rows.sort((a,b)=>b.inv-a.inv).slice(0,10).map(r=>({l:r.name,v:Math.max(0,r.inv),v2:dim==="svc"?undefined:Math.max(0,r.cash),go:["invoices",dim==="svc"||dim==="method"?{}:{[dim]:r.id,per:f.per,from:f.from,to:f.to}]})))}</section><div>${biTable(key,cols,rows,{sort:"inv"})}</div></div>`}
