/* ===== v61 · Facturation & Revenus — payments: record, transactions, partial payments, refunds, methods, reconciliation ===== */
const biMethodName=(k: string)=>L4((BI_METHODS.find(m=>m[0]===k)||[0,k])[1]);
/* ---------- payment form (dialog and page share it) ---------- */
function biOpenInvs(party: string){return BI.st!.invoices.filter(i=>i.party===party&&i.status==="issued"&&biBal(i)>0).sort((a,b)=>a.due!<b.due!?-1:1)}
function biPayFormHTML(st: BiPaySt){const S=BI.st;const invs=st.party?biOpenInvs(st.party):[];const cur=S!.set.cur;const credit=st.party?biPartyCredit(st.party):0;const ms=S!.set.methods||BI_METHODS.map(m=>m[0]);
  return `<div class="bi-flds"><div class="bi-fld full"><label>${biE(L4("Payeur (patient ou organisme)|Payer (patient or organisation)|Zahler|الدافع"))} <em>*</em></label><select class="bi-in" data-pp="party">${biOpts(biPartyOpts(),st.party,{any:"—"})}</select></div>
   <div class="bi-fld"><label>${biE(biW("date"))} <em>*</em></label><input type="date" class="bi-in" data-pp="date" value="${biE(st.date)}" max="${biToday()}"></div><div class="bi-fld"><label>${biE(biW("amount"))} (${biE(cur)}) <em>*</em></label><input class="bi-in num big" data-pp="amount" inputmode="decimal" value="${biE(st.amountRaw??"")}" autocomplete="off"></div>
   <div class="bi-fld"><label>${biE(biW("method"))}</label><select class="bi-in" data-pp="method">${biOpts(BI_METHODS.filter(m=>ms.includes(m[0])).map(([k,l])=>[k,L4(l)]),st.method)}</select></div><div class="bi-fld"><label>${biE(L4("Référence externe (transaction, chèque…)|External reference (transaction, cheque…)|Externe Referenz|المرجع الخارجي"))}</label><input class="bi-in" data-pp="ref" value="${biE(st.ref||"")}"></div>
   <div class="bi-fld"><label>${biE(L4("Statut de la transaction|Transaction status|Transaktionsstatus|حالة المعاملة"))}</label><select class="bi-in" data-pp="status">${biOpts([["ok",L4(BI_STATES.ok[0])],["pending",L4("En attente de confirmation (ne compte pas encore)|Awaiting confirmation (not counted yet)|Ausstehend (zählt noch nicht)|قيد الانتظار")]],st.status||"ok")}</select></div></div>
   <div class="bi-alloc"><h4>${bii("layers",14)}${biE(L4("Affectation aux factures|Allocation to invoices|Zuordnung zu Rechnungen|التخصيص للفواتير"))}</h4>${!st.party?`<p class="bi-mut sm">${biE(L4("Choisissez d’abord le payeur.|Choose the payer first.|Zuerst Zahler wählen.|اختر الدافع أولًا."))}</p>`:invs.length?`<table class="bi-tb bi-tbm"><thead><tr><th></th><th>${biE(L4("Facture|Invoice|Rechnung|الفاتورة"))}</th><th>${biE(biW("due"))}</th><th class="num">${biE(biW("balance"))}</th><th class="num">${biE(L4("Montant affecté|Allocated|Zugeordnet|المخصص"))}</th></tr></thead><tbody>${invs.map(i=>{const a=st.alloc[i.id];return `<tr${biOverdue(i)?' class="late"':""}><td><input type="checkbox" data-pac="${i.id}"${a!==undefined?" checked":""} aria-label="${biE(i.no)}"></td><td class="bi-mono">${biE(i.no)}</td><td>${biE(biFmtDate(i.due))}</td><td class="num">${biE(biM(biBal(i),cur))}</td><td class="num"><input class="bi-in sm num" data-paa="${i.id}" inputmode="decimal" value="${biE(a!==undefined?(st.allocRaw?.[i.id]??biM(a,cur,{plain:true})):"")}"${a===undefined?" disabled":""} aria-label="${biE(L4("Montant affecté|Allocated|Zugeordnet|المخصص"))} ${biE(i.no)}"></td></tr>`}).join("")}</tbody></table>`:`<p class="bi-mut sm">${biE(L4("Aucune facture ouverte pour ce payeur : le paiement sera conservé en avoir client.|No open invoice for this payer: the payment will be kept as customer credit.|Keine offene Rechnung: Betrag wird Guthaben.|لا فواتير مفتوحة."))}</p>`}
   <div class="bi-pasum" data-pasum>${biPaySumHTML(st)}</div><label class="bi-chk"><input type="checkbox" data-pp="credit"${st.credit?" checked":""}><span>${biE(L4("Conserver un éventuel excédent en avoir client (remboursable)|Keep any excess as customer credit (refundable)|Überschuss als Guthaben behalten|الاحتفاظ بالفائض كرصيد"))}</span></label>${credit>0?`<p class="bi-note">${bii("wallet",14)}${biE(L4("Avoir déjà disponible pour ce payeur : |Credit already available for this payer: |Vorhandenes Guthaben: |رصيد متاح: "))}<b>${biE(biM(credit,cur))}</b> — ${biE(L4("affectez-le depuis Transactions.|apply it from Transactions.|in Transaktionen zuordnen.|خصصه من المعاملات."))}</p>`:""}</div>`}
function biPaySumHTML(st: BiPaySt){const cur=BI.st!.set.cur;const al=Object.values(st.alloc).reduce((s,v)=>s!+(v||0),0);const amt=st.amount||0;const rest=amt-al!;return `<span>${biE(L4("Affecté|Allocated|Zugeordnet|المخصص"))} <b>${biE(biM(al,cur))}</b></span><span class="${rest<0?"bad":rest>0?"warn":"ok"}">${biE(rest<0?L4("Excès d’affectation|Over-allocated|Überzuordnung|تخصيص زائد"):L4("Non affecté|Unallocated|Nicht zugeordnet|غير مخصص"))} <b>${biE(biM(Math.abs(rest),cur))}</b></span>`}
/* fill allocations oldest due first */
function biAutoAlloc(st: BiPaySt){st.alloc={};st.allocRaw={};if(!st.party||!st.amount)return;let left=st.amount;const list=biOpenInvs(st.party);if(st.only){const i=list.findIndex(x=>x.id===st.only);if(i>0)list.unshift(list.splice(i,1)[0])}for(const i of list){if(left<=0)break;const a=Math.min(left,biBal(i));st.alloc[i.id]=a;left-=a}}
function biPayBind(root: HTMLElement,st: BiPaySt,onDone?: (p: BiPayT) => void){const repaint=(full?: boolean)=>{if(full){root.querySelector<HTMLInputElement>("[data-payform]")!.innerHTML=biPayFormHTML(st)}else root.querySelector<HTMLInputElement>("[data-pasum]")!.innerHTML=biPaySumHTML(st)};
  root.addEventListener("input",e=>{const x=tgt(e);if(x.matches("[data-pp=amount]")){st.amountRaw=x.value;try{st.amount=biParseMoney(x.value||"0",biCurD(BI.st!.set.cur));x.classList.remove("bad")}catch(err){st.amount=0;x.classList.add("bad")}if(!st.touched){biAutoAlloc(st);const keep=x.selectionStart;repaint(true);const n=root.querySelector<HTMLInputElement>("[data-pp=amount]");n!.focus();n!.setSelectionRange(keep,keep)}else repaint()}
    if(x.matches("[data-paa]")){st.touched=true;(st.allocRaw=st.allocRaw||{})[x.dataset.paa!]=x.value;try{st.alloc[x.dataset.paa!]=biParseMoney(x.value||"0",biCurD(BI.st!.set.cur));x.classList.remove("bad")}catch(err){x.classList.add("bad")}repaint()}
    if(x.matches("[data-pp=ref]"))st.ref=x.value});
  root.addEventListener("change",e=>{const x=tgt(e);if(x.matches("[data-pp=party]")){st.party=x.value;st.touched=false;biAutoAlloc(st);repaint(true)}else if(x.matches("[data-pp=date],[data-pp=method],[data-pp=status]"))(st as unknown as Dict)[x.dataset.pp!]=x.value;else if(x.matches("[data-pp=credit]"))st.credit=x.checked;
    else if(x.matches("[data-pac]")){st.touched=true;const id=x.dataset.pac;if(x.checked){const al=Object.values(st.alloc).reduce((s,v)=>s!+v!,0);st.alloc[id!]=Math.max(0,Math.min(biBal(biInv(id)!),(st.amount||0)-al!))}else{delete st.alloc[id!];delete st.allocRaw?.[id!]}repaint(true)}})}
function biPaySubmit(st: BiPaySt,force?: boolean){const alloc=Object.entries(st.alloc).filter(([,v])=>v!>0).map(([inv,amt])=>({inv,amt}) as BiAlloc);const p=biPay({party:st.party,date:st.date,amount:st.amount!,method:st.method,ref:st.ref,status:st.status,alloc,credit:st.credit,idem:st.idem,force,cur:BI.st!.set.cur});return p}
function biPayDlg(o: { party?: string; inv?: string; only?: string }={}){if(!biCan("pay.record")){biToast(biW("denied"));return}const st: BiPaySt={party:o.party||"",date:biToday(),amount:0,method:"card",ref:"",status:"ok",alloc:{},credit:false,idem:biId("k"),only:o.inv||null};
  if(o.inv){const i=biInv(o.inv);st.amount=biBal(i!);st.amountRaw=biM(st.amount,i!.cur,{plain:true});st.alloc={[o.inv]:st.amount};st.touched=false}
  const finish=(p: BiPayT)=>{biSave(true);biToast(L4("Paiement enregistré : |Payment recorded: |Zahlung erfasst: |سُجلت الدفعة: ")+p.no+" · "+biM(p.amount,p.cur));biRefresh();if(BI.ui.drawer)biDrawerPaint();const R=biRoot();R!.querySelectorAll<HTMLInputElement>('[data-st="paid"]').forEach(b=>{if(!biRM())b.animate([{transform:"scale(.6)",opacity:.2},{transform:"scale(1.12)"},{transform:"none",opacity:1}],{duration:420})})};
  biDialog(L4("Enregistrer un paiement|Record a payment|Zahlung erfassen|تسجيل دفعة"),`<div data-payform>${biPayFormHTML(st)}</div>`,{wide:true,okLabel:L4("Enregistrer le paiement|Record payment|Zahlung erfassen|تسجيل الدفعة"),mount:m=>biPayBind(m,st),
   onOk:m=>{if(!st.amount)throw new BiErr("bi_eReq",biW("amount"));try{finish(biPaySubmit(st,false));return true}catch(e){if((e as BiErr).k==="bi_eDupPay"){m.remove();biConfirm(biErr(e),()=>{try{finish(biPaySubmit(st,true))}catch(err){biToast(biErr(err))}},{okLabel:L4("Enregistrer quand même|Record anyway|Trotzdem erfassen|التسجيل رغم ذلك")});return false}throw e}}})}

