biDef("record","pay",{n:"Enregistrer un paiement|Record a payment|Zahlung erfassen|تسجيل دفعة",ic:"coin",perm:"pay.record",page:()=>{const st=BI.ui.payst=BI.ui.payst||{party:"",date:biToday(),amount:0,method:"card",ref:"",status:"ok",alloc:{},credit:false,idem:biId("k")};
  return `<div class="bi-recp"><section class="bi-card"><div data-payform>${biPayFormHTML(st)}</div><p class="bi-err sm" data-recerr hidden></p><div class="bi-acts end"><button type="button" class="bi-btn" data-bireset>${bii("undo",14)}${biE(L4("Vider|Clear|Leeren|مسح"))}</button><button type="button" class="bi-btn pri" data-birecok>${bii("check",15)}${biE(L4("Enregistrer le paiement|Record payment|Zahlung erfassen|تسجيل الدفعة"))}</button></div></section>
   <aside class="bi-card bi-tips"><h3>${bii("info",16)}${biE(L4("Règles appliquées|Rules applied|Angewandte Regeln|القواعد المطبقة"))}</h3><ul><li>${biE(L4("Un paiement partiel met à jour le reste dû et passe la facture en « partiellement payée ».|A partial payment updates the balance and marks the invoice partially paid.|Teilzahlung aktualisiert den Saldo.|الدفع الجزئي يحدث الرصيد."))}</li><li>${biE(L4("Une facture ne peut pas recevoir plus que son reste dû ; l’excédent devient un avoir client seulement si vous le demandez.|An invoice cannot receive more than its balance; excess becomes customer credit only if you ask.|Keine Überzahlung je Rechnung.|لا يمكن تجاوز رصيد الفاتورة."))}</li><li>${biE(L4("Un paiement identique (payeur, montant, date, moyen) déclenche une alerte de doublon.|An identical payment (payer, amount, date, method) raises a duplicate warning.|Identische Zahlung löst Warnung aus.|الدفعة المطابقة تطلق تحذيرًا."))}</li><li>${biE(L4("« En attente » ne compte pas comme encaissé tant qu’il n’est pas confirmé.|“Pending” does not count as collected until confirmed.|„Ausstehend“ zählt nicht als Eingang.|«قيد الانتظار» لا يُحتسب."))}</li><li>${biE(L4("Aucun prestataire de paiement n’est connecté : rien n’est débité depuis cet écran.|No payment provider is connected: nothing is charged from this screen.|Kein Zahlungsanbieter verbunden.|لا يوجد مزود دفع متصل."))}</li></ul></aside></div>`},
 mount:R=>{biPayBind(R.querySelector<HTMLInputElement>(".bi-recp")!,BI.ui.payst!)},click:(e,c)=>{const R=biRoot();if(c("[data-bireset]")){BI.ui.payst=null;biRefresh();return}if(c("[data-birecok]")){const st=BI.ui.payst;const er=R!.querySelector<HTMLInputElement>("[data-recerr]");er!.hidden=true;
  const done=(p: BiPayT)=>{biSave(true);BI.ui.payst=null;biToast(L4("Paiement enregistré : |Payment recorded: |Zahlung erfasst: |سُجلت الدفعة: ")+p.no);biGo("transactions",{});setTimeout(()=>biDrawer("pay",p.id),250)};
  try{if(!st!.amount)throw new BiErr("bi_eReq",biW("amount"));done(biPaySubmit(st!,false))}catch(err){if((err as BiErr).k==="bi_eDupPay"){biConfirm(biErr(err),()=>{try{done(biPaySubmit(st!,true))}catch(e2){biToast(biErr(e2))}},{okLabel:L4("Enregistrer quand même|Record anyway|Trotzdem erfassen|التسجيل رغم ذلك")})}else{er!.textContent=biErr(err);er!.hidden=false;if(!biRM())er!.animate([{transform:"translateX(-5px)"},{transform:"translateX(5px)"},{transform:"none"}],{duration:240})}}}}});

