biDef("partial","pay",{n:"Paiements partiels|Partial payments|Teilzahlungen|المدفوعات الجزئية",ic:"half",perm:"pay.view",badge:()=>BI.st!.invoices.filter(i=>biScope(i)&&i.status==="issued"&&biPayState(i)==="partial").length,page:()=>{const rows=BI.st!.invoices.filter(i=>biScope(i)&&i.status==="issued"&&biPayState(i)==="partial").map(i=>{const ps=BI.st!.payments.filter(p=>p.status==="ok"&&p.alloc.some(a=>a.inv===i.id));return {id:i.id,i,no:i.no,party:biPartyName(i.party),total:biDocTotal(i),paid:biPaid(i),bal:biBal(i),n:ps.length,last:ps.map(p=>p.date).sort().pop()||"",due:i.due,late:biDaysLate(i)}});
  const cols: BiCol<(typeof rows)[number]>[]=[{k:"no",l:"Facture|Invoice|Rechnung|الفاتورة",v:r=>r.no,h:r=>`<b class="bi-mono">${biE(r.no)}</b>`},{k:"party",l:BIW.party,v:r=>r.party},{k:"total",l:BIW.total,num:true,v:r=>r.total,h:r=>biE(biM(r.total))},{k:"paid",l:BIW.paid,num:true,v:r=>r.paid,h:r=>`${biE(biM(r.paid))}<span class="bi-share sm"><i style="--w:${(r.paid*100/r.total).toFixed(1)}%"></i></span>`},{k:"bal",l:BIW.balance,num:true,v:r=>r.bal,h:r=>`<b class="bi-bal">${biE(biM(r.bal))}</b>`},{k:"n",l:"Versements|Instalments|Raten|الدفعات",num:true,v:r=>r.n},{k:"last",l:"Dernier versement|Last payment|Letzte Zahlung|آخر دفعة",v:r=>r.last,h:r=>biE(biFmtDate(r.last))},{k:"due",l:BIW.due,v:r=>r.due,h:r=>`${biE(biFmtDate(r.due))}${r.late?`<small class="bi-late">+${biNf(r.late)} j</small>`:""}`},{k:"act",l:BIW.actions,nosort:true,fixed:true,h:r=>biCan("pay.record")?`<button type="button" class="bi-btn sm pri" data-bipay="${r.i.party}|${r.id}">${bii("coin",13)}${biE(L4("Solder|Settle|Begleichen|تسوية"))}</button>`:""}];BI_TBL.partial={cols,rows,open:id=>biDrawer("inv",id)};
  return `<p class="bi-desc">${biE(L4("Factures émises ayant reçu au moins un versement sans être soldées.|Issued invoices that received at least one payment without being settled.|Teilweise bezahlte Rechnungen.|فواتير مدفوعة جزئيًا."))}</p>${biTable("partial",cols,rows,{click:true,sort:"bal"})}`}});

