function biRefundDlg(party?: string | null,cn?: string | null){if(!biCan("pay.refund")){biToast(biW("denied"));return}const cands=BI.st!.parties.filter(p=>biPartyCredit(p.id)>0);if(!cands.length){biToast(L4("Aucun patient n’a d’avoir remboursable.|No patient has refundable credit.|Kein erstattbares Guthaben.|لا رصيد قابل للاسترداد."));return}party=party||cands[0].id;
  biDialog(L4("Créer un remboursement|Create a refund|Erstattung anlegen|إنشاء استرداد"),`<p class="bi-cmsg">${biE(L4("Un remboursement puise dans l’avoir client (trop-perçu ou avoir sur facture déjà payée). Il reste « à effectuer » tant que le virement ou l’annulation de carte n’est pas confirmé.|A refund draws on customer credit (overpayment or credit note on a paid invoice). It stays pending until the transfer or card reversal is confirmed.|Erstattung aus Guthaben; ausstehend bis Bestätigung.|يُسحب الاسترداد من رصيد العميل."))}</p><div class="bi-flds"><div class="bi-fld full"><label>${biE(biW("party"))}</label><select class="bi-in" data-rf="party">${biOpts(cands.map(p=>[p.id,biPartyName(p.id)+" — "+L4("avoir|credit|Guthaben|رصيد")+" "+biM(biPartyCredit(p.id))]),party)}</select></div>
   <div class="bi-fld"><label>${biE(biW("amount"))}</label><input class="bi-in num" data-rf="amount" value="${biE(biM(biPartyCredit(party),null,{plain:true}))}"></div><div class="bi-fld"><label>${biE(biW("method"))}</label><select class="bi-in" data-rf="method">${biOpts(BI_METHODS.map(([k,l])=>[k,L4(l)]),"transfer")}</select></div><div class="bi-fld full"><label>${biE(L4("Motif|Reason|Grund|السبب"))}</label><input class="bi-in" data-rf="reason"></div></div>`,
  {okLabel:L4("Créer le remboursement|Create refund|Erstattung anlegen|إنشاء الاسترداد"),mount:m=>m.querySelector<HTMLInputElement>("[data-rf=party]")!.addEventListener("change",ev=>{m.querySelector<HTMLInputElement>("[data-rf=amount]")!.value=biM(biPartyCredit(tgt(ev).value),null,{plain:true})}),
   onOk:m=>{const v: Dict={};m.querySelectorAll<HTMLInputElement>("[data-rf]").forEach(i=>v[i.dataset.rf!]=i.value.trim());const amt=biParseMoney(v.amount,biCurD(biCur()));if(!v.reason)throw new BiErr("bi_eReq",L4("Motif|Reason|Grund|السبب"));const r=biRefund({party:v.party,amount:amt!,method:v.method,reason:v.reason,cn:cn||null});biSave(true);biToast(L4("Remboursement créé : |Refund created: |Erstattung: |أنشئ الاسترداد: ")+r.no);biRefresh();if(BI.ui.drawer)biDrawerPaint();return true}})}
biDef("refunds","pay",{n:"Remboursements|Refunds|Erstattungen|الاستردادات",ic:"undo",perm:"pay.view",badge:()=>BI.st!.refunds.filter(r=>r.status==="pending").length,page:()=>{const f=biFlt("refunds");const [pf,pt]=biPerRange(f);const rows=BI.st!.refunds.map(r=>({id:r.id,r,no:r.no,date:r.date,party:biPartyName(r.party),amount:r.amount,method:r.method,cn:BI.st!.credits.find(c=>c.id===r.cn)?.no||"",reason:r.reason,st:r.status})).filter(r=>biInRange(r.date,pf,pt)&&(!f.st||r.st===f.st)&&(!f.q||(r.no+" "+r.party+" "+r.cn).toLowerCase().includes(f.q.toLowerCase())));
  const cols: BiCol<(typeof rows)[number]>[]=[{k:"no",l:"N°|No.|Nr.|رقم",v:r=>r.no,h:r=>`<b class="bi-mono">${biE(r.no)}</b>`},{k:"date",l:BIW.date,v:r=>r.date,h:r=>biE(biFmtDate(r.date))},{k:"party",l:BIW.party,v:r=>r.party},{k:"amount",l:BIW.amount,num:true,v:r=>r.amount,h:r=>biE(biM(r.amount))},{k:"method",l:BIW.method,v:r=>r.method,h:r=>biE(biMethodName(r.method))},{k:"cn",l:"Avoir lié|Linked credit note|Gutschrift|الإشعار",v:r=>r.cn,h:r=>`<span class="bi-mono">${biE(r.cn||"—")}</span>`},{k:"reason",l:"Motif|Reason|Grund|السبب",v:r=>r.reason,h:r=>`<span class="bi-clip">${biE(r.reason)}</span>`},{k:"st",l:BIW.status,v:r=>r.st,h:r=>biSt8(r.st)},
   {k:"act",l:BIW.actions,nosort:true,fixed:true,h:r=>r.st==="pending"&&biCan("pay.refund")?`<button type="button" class="bi-btn sm pri" data-birfst="${r.id}|done">${bii("check",13)}${biE(L4("Effectué|Completed|Erledigt|منجز"))}</button><button type="button" class="bi-btn sm" data-birfst="${r.id}|failed">${biE(L4("Échec|Failed|Fehlgeschlagen|فشل"))}</button>`:""}];BI_TBL.refunds={cols,rows};
  return `${biFltHTML("refunds",f,{states:["pending","done","failed"],prac:false,est:false})}${biCan("pay.refund")?`<div class="bi-acts end"><button type="button" class="bi-btn pri" data-birefund="|">${bii("plus",15)}${biE(L4("Créer un remboursement|Create a refund|Erstattung anlegen|إنشاء استرداد"))}</button></div>`:""}${biTable("refunds",cols,rows,{sort:"date"})}`},
 click:(e,c)=>{const x=c("[data-birfst]");if(x){const [id,st]=x.dataset.birfst!.split("|");biAct(()=>biRefundStatus(id,st),biW("saved"));biRefresh()}}});

/* ---------- payment methods ---------- */
biDef("methods","pay",{n:"Moyens de paiement|Payment methods|Zahlungsarten|وسائل الدفع",ic:"card",perm:"pay.view",page:()=>{const S=BI.st;const on=S!.set.methods||BI_METHODS.map(m=>m[0]);const from=biAddMonths(biToday(),-12);const st: Record<string, { n: number; v: number }>={};S!.payments.forEach(p=>{if(p.status==="ok"&&p.date>=from){const o=(st[p.method]=st[p.method]||{n:0,v:0});o.n++;o.v+=p.amount}});
  return `<p class="bi-desc">${biE(L4("Les moyens actifs apparaissent sur les factures et dans la saisie des paiements. Les paiements en ligne exigent un prestataire connecté par un adaptateur ; aucun n’est connecté dans cette démonstration.|Active methods appear on invoices and in payment entry. Online payments need a provider connected through an adapter; none is connected in this demo.|Online-Zahlungen benötigen einen verbundenen Anbieter (keiner verbunden).|الدفع الإلكتروني يتطلب مزودًا متصلًا."))}</p><div class="bi-mgrid">${BI_METHODS.map(([k,l],i)=>`<div class="bi-card bi-meth" style="--i:${i}"><header><span class="ic">${bii({card:"card",cash:"coin",transfer:"bank",cheque:"file",sepa:"bank",thirdparty:"building",online:"plug"}[k]!,18)}</span><b>${biE(L4(l))}</b><label class="bi-sw"><input type="checkbox" data-bimeth="${k}"${on.includes(k)?" checked":""}${biCan("cfg.edit")?"":" disabled"}><i></i><span class="sr">${biE(L4("Actif|Active|Aktiv|نشط"))}</span></label></header><p><b>${biE(biM(st[k]?.v||0))}</b> · ${biNf(st[k]?.n||0)} ${biE(L4("paiements sur 12 mois|payments over 12 months|Zahlungen in 12 Monaten|دفعة في 12 شهرًا"))}</p>${k==="online"||k==="sepa"?`<p class="bi-mut sm">${bii("plug",12)} ${biE(L4("Prestataire : |Provider: |Anbieter: |المزود: "))}${biSt8("notconn")}</p>`:""}</div>`).join("")}</div>`},
 change:e=>{const x=tgt(e);if(x.matches("[data-bimeth]")){const S=BI.st;let on: (string | undefined)[]=S!.set.methods||BI_METHODS.map(m=>m[0]);on=x.checked?[...new Set([...on,x.dataset.bimeth])]:on.filter(m=>m!==x.dataset.bimeth);if(!on.length){x.checked=true;biToast(L4("Au moins un moyen doit rester actif.|At least one method must stay active.|Mindestens eine Zahlungsart.|يجب إبقاء وسيلة واحدة."));return}S!.set.methods=on;biLog("cfg.edit","set","methods",on.join(", "));biSave()}}});

