function biReconSuggest(){const S=BI.st;const out: BiRecon[]=[];const used=new Set();S!.bank.filter(b=>!b.match).forEach(b=>{let best=null as BiRecon | null;S!.payments.forEach(p=>{if(used.has(p.id)||p.status!=="ok"||p.recon!=="unmatched")return;const dd=Math.abs(biDays(p.date,b.date));if(dd>6)return;const diff=Math.abs(p.amount-b.amount);const score=(diff===0?0:diff<=200?50:999)+dd;if(score<999&&(!best||score<best.score))best={b,p,score,diff}});if(best){used.add(best.p.id);out.push(best)}});return out}
function biReconMatch(bid: string,pid: string,note?: string){biNeed("pay.recon");const S=BI.st;const b=S!.bank.find(x=>x.id===bid),p=S!.payments.find(x=>x.id===pid);if(!b||!p)throw new BiErr("bi_eNotFound");b.match=p.id;p.recon=b.amount===p.amount?"matched":"discrepancy";p.bank=b.id;if(note)p.note=(p.note?p.note+" · ":"")+note;biLog("pay.recon","pay",p.id,p.no+" ↔ "+b.label+(b.amount!==p.amount?" · "+L4("écart|discrepancy|Abweichung|فرق")+" "+biM(b.amount-p.amount,p.cur):""))}
function biDupGroups(){const g: Record<string, BiPayT[]>={};BI.st!.payments.forEach(p=>{if(p.status==="failed"||p.status==="reversed")return;const k=[p.party,p.amount,p.date,p.method].join("|");(g[k]=g[k]||[]).push(p)});return Object.values(g).filter(a=>a.length>1)}
