/* ---------- forms adapter: reads the Forms app store, never writes to it ---------- */
biFormList=function(){try{if(typeof feLoad==="function"){feLoad();const lab=(s: unknown)=>(typeof s==="string"&&/^fe_/.test(s)&&typeof t==="function"?t(s):s) as string;return feS!.forms.filter(e=>!e.arch).map(e=>{const d=feS!.docs[e.id];const fields: { k: string; l: string }[]=[];if(d)d.pages.forEach(p=>p.sections.forEach(s=>feWalk(s.fields,f=>{if(f&&f.type&&!["group","heading","text","divider","image","html"].includes(f.type))fields.push({k:f.id,l:lab(f.label)||f.id})},s,s)));return {id:e.id,name:e.name?lab(e.name):(d?.title?lab(d.title):e.id),status:e.status,fields,loaded:!!d}})}}catch(e){console.warn(e)}return []};
const biFormName=(id: string)=>biFormList().find(f=>f.id===id)?.name||id;

