const biNameIn=(n: string | null | undefined,attr: string)=>`<input class="bi-in" ${attr} value="${biE(L4(n||""))}">`;
/* store a name typed in the current language inside a 4-language string */
function biSetL4(old: string | null | undefined,val: string){const p=String(old||"").split("|");while(p.length<4)p.push(p[0]||val);const i={fr:0,en:1,de:2,ar:3}[lang()]??0;p[i]=val;if(!old)return [val,val,val,val].join("|");return p.join("|")}
