biDef("taxes","cat",{n:"Configuration des taxes|Tax configuration|Steuerkonfiguration|إعداد الضرائب",ic:"pct",perm:"cat.view",page:()=>{const S=BI.st;const ed=biCan("cfg.edit");return `<p class="bi-note warn">${bii("warn",14)}${biE(L4("Taux et mentions proposés par défaut pour la juridiction choisie, à confirmer par un administrateur ou votre expert-comptable. L’exonération des soins ne s’applique que si ses conditions légales sont remplies. Les catégories non confirmées déclenchent un avertissement à l’émission.|Default rates and mentions for the chosen jurisdiction, to be confirmed by an administrator or your accountant. The care exemption applies only when its legal conditions are met. Unconfirmed categories raise a warning when issuing.|Standardsätze, vom Admin/Steuerberater zu bestätigen.|معدلات افتراضية يجب تأكيدها."))}</p>
  <div class="bi-tbs"><table class="bi-tb"><thead><tr><th>${biE(L4("Catégorie|Category|Kategorie|الفئة"))}</th><th class="num">${biE(L4("Taux|Rate|Satz|المعدل"))}</th><th>${biE(L4("Mention imprimée|Printed mention|Gedruckter Vermerk|العبارة المطبوعة"))}</th><th>${biE(L4("Utilisée par|Used by|Verwendet von|مستخدمة في"))}</th><th>${biE(BIW.status)}</th></tr></thead><tbody>${S!.taxes.map(t=>`<tr><td><b>${biE(L4(t.n))}</b></td><td class="num">${ed?`<input class="bi-in sm num" data-tx="${t.id}|bp" value="${biE(String(t.bp/100).replace(".",","))}" aria-label="${biE(L4("Taux|Rate|Satz|المعدل"))}">`:biE(biPct(t.bp,2))}</td><td>${ed?`<input class="bi-in sm" data-tx="${t.id}|mention" value="${biE(t.mention||"")}">`:biE(t.mention||"—")}</td><td>${biNf(S!.services.filter(s=>s.tax===t.id).length)} ${biE(L4("prestation(s)|service(s)|Leistung(en)|خدمة"))}</td><td>${ed?`<label class="bi-sw"><input type="checkbox" data-txv="${t.id}"${t.verified?" checked":""}><i></i><span>${biSt8(t.verified?"verified":"unverified")}</span></label>`:biSt8(t.verified?"verified":"unverified")}</td></tr>`).join("")}</tbody></table></div><p class="bi-mut sm">${biE(L4("Modifier un taux n’affecte pas les factures déjà émises : leur TVA est figée dans leur instantané.|Changing a rate does not affect issued invoices: their tax is frozen in their snapshot.|Änderungen betreffen keine ausgestellten Rechnungen.|التغيير لا يؤثر على الفواتير الصادرة."))}</p>`},
 change:e=>{const x=tgt(e);const S=BI.st;if(x.matches("[data-tx]")){const [id,k]=x.dataset.tx!.split("|");const t=S!.taxes.find(z=>z.id===id);if(k==="bp"){try{const v=biParseMoney(x.value,2);if(v!<0||v!>10000)throw new BiErr("bi_eDisc");t!.bp=v!;x.classList.remove("bad")}catch(err){x.classList.add("bad");biToast(biErr(err));return}}else t!.mention=x.value;t!.verified=false;biLog("cfg.edit","tax",id,L4(t!.n)+" "+biPct(t!.bp,2));biChanged()}
  if(x.matches("[data-txv]")){const t=S!.taxes.find(z=>z.id===x.dataset.txv);t!.verified=x.checked;t!.verifiedBy=x.checked?"Nassim · "+biToday():null;biLog("cfg.edit","tax",t!.id,L4(t!.n)+" : "+(x.checked?"verified":"unverified"));biChanged()}}});

/* ---------- payers and official references ---------- */
biDef("payers","cat",{n:"Payeurs et références|Payers and references|Kostenträger und Referenzen|الدافعون والمراجع",ic:"bank",perm:"cat.view",page:()=>{const S=BI.st;const ed=biCan("cfg.edit");return `<section class="bi-card"><header class="bi-ch"><h3>${bii("bank",16)}${biE(L4("Payeurs|Payers|Kostenträger|الدافعون"))}</h3>${ed?`<button type="button" class="bi-btn sm" data-bipy>${bii("plus",14)}${biE(L4("Ajouter|Add|Hinzufügen|إضافة"))}</button>`:""}</header><ul class="bi-list">${S!.payers.map(p=>`<li><span class="ic">${bii(p.kind==="patient"?"user":"building",14)}</span><div><b>${biE(p.name)}</b><small>${biE(L4({patient:"Paiement direct par le patient|Direct patient payment|Direktzahlung|دفع مباشر",mutual:"Complémentaire santé|Supplementary insurer|Zusatzversicherung|تأمين تكميلي",statutory:"Régime obligatoire|Statutory scheme|Gesetzliche Versicherung|نظام إلزامي",org:"Organisation|Organisation|Organisation|مؤسسة"}[p.kind]||p.kind))}${p.ref?" · "+biE(p.ref):""}</small></div>${biSt8(p.verified?"verified":"unverified")}${ed&&p.id!=="self"?`<button type="button" class="bi-ib sm" data-bipyv="${p.id}" aria-label="${biE(L4("Basculer la vérification|Toggle verification|Prüfung umschalten|تبديل التوثيق"))}">${bii("check",14)}</button>`:""}</li>`).join("")}</ul><p class="bi-mut sm">${biE(L4("Aucune règle d’éligibilité ni taux de remboursement n’est appliqué automatiquement. Les droits du patient sont vérifiés auprès du payeur, hors de cette application.|No eligibility rule or reimbursement rate is applied automatically. Patient rights are checked with the payer, outside this app.|Keine automatische Erstattungslogik.|لا تُطبق قواعد الأهلية تلقائيًا."))}</p></section>
  <section class="bi-card"><header class="bi-ch"><h3>${bii("lib",16)}${biE(L4("Nomenclatures et tarifs officiels|Official nomenclatures and tariffs|Amtliche Nomenklaturen|التسميات والتعرفات الرسمية"))}</h3>${ed?`<button type="button" class="bi-btn sm" data-bitf>${bii("plus",14)}${biE(L4("Ajouter une référence sourcée|Add a sourced reference|Quellreferenz hinzufügen|إضافة مرجع موثق"))}</button>`:""}</header>
   <p class="bi-desc">${biE(L4("France : CCAM (actes techniques) et NGAP (actes cliniques et paramédicaux) sont des référentiels distincts, versionnés, publiés par l’Assurance maladie. Tunisie et autres pays : configuration séparée par juridiction. Rien n’est préchargé : chaque code doit être saisi avec sa source, sa version et vérifié par un administrateur.|France: CCAM (technical acts) and NGAP (clinical and allied-health acts) are distinct, versioned reference systems. Tunisia and other countries: separate configuration per jurisdiction. Nothing is preloaded: each code must be entered with its source and version and verified by an administrator.|Nichts vorgeladen; jede Referenz mit Quelle und Prüfung.|لا شيء محمّل مسبقًا."))}</p>
   ${(S!.tariffs||[]).length?`<div class="bi-tbs"><table class="bi-tb"><thead><tr><th>${biE(L4("Système|System|System|النظام"))}</th><th>Code</th><th>${biE(L4("Libellé|Label|Bezeichnung|التسمية"))}</th><th class="num">${biE(biW("amount"))}</th><th>${biE(L4("Source et version|Source and version|Quelle und Version|المصدر والإصدار"))}</th><th>${biE(BIW.status)}</th></tr></thead><tbody>${S!.tariffs.map(t=>`<tr><td>${biE(t.sys)}</td><td class="bi-mono">${biE(t.code)}</td><td>${biE(t.label)}</td><td class="num">${t.amount!=null?biE(biM(t.amount)):"—"}</td><td><small>${biE(t.src)} · ${biE(t.ver)}</small></td><td>${ed?`<label class="bi-sw"><input type="checkbox" data-bitfv="${biE(t.code)}"${t.verified?" checked":""}><i></i><span>${biSt8(t.verified?"verified":"unverified")}</span></label>`:biSt8(t.verified?"verified":"unverified")}</td></tr>`).join("")}</tbody></table></div>`:biEmpty("lib",L4("Aucune référence officielle configurée. Les prestations sont facturées au tarif libre du cabinet.|No official reference configured. Services are billed at the practice’s free price.|Keine amtlichen Referenzen konfiguriert.|لا مراجع رسمية."))}</section>`},
 click:(e,c)=>{const S=BI.st;let x: HTMLInputElement | null;if((x=c("[data-bipyv]"))){const p=S!.payers.find(z=>z.id===x!.dataset.bipyv);p!.verified=!p!.verified;biLog("cfg.edit","payer",p!.id,p!.name+" : "+(p!.verified?"verified":"unverified"));biChanged();return}
  if(c("[data-bipy]")){biDialog(L4("Nouveau payeur|New payer|Neuer Kostenträger|دافع جديد"),`<div class="bi-flds"><div class="bi-fld full"><label>${biE(L4("Nom|Name|Name|الاسم"))}</label><input class="bi-in" data-yv="name" autofocus></div><div class="bi-fld"><label>${biE(L4("Type|Type|Typ|النوع"))}</label><select class="bi-in" data-yv="kind">${biOpts([["mutual","Complémentaire santé|Supplementary insurer|Zusatzversicherung|تأمين تكميلي"],["statutory","Régime obligatoire|Statutory scheme|Gesetzlich|إلزامي"],["org","Organisation|Organisation|Organisation|مؤسسة"]].map(([k,l])=>[k,L4(l)]),"mutual")}</select></div><div class="bi-fld"><label>${biE(L4("Identifiant / convention|Identifier / agreement|Kennung|المعرف"))}</label><input class="bi-in" data-yv="ref"></div></div>`,{onOk:m=>{const g=(k: string)=>m.querySelector<HTMLInputElement>(`[data-yv="${k}"]`)!.value.trim();if(!g("name"))throw new BiErr("bi_eReq",L4("Nom|Name|Name|الاسم"));S!.payers.push({id:biId("py"),name:g("name"),kind:g("kind"),ref:g("ref"),verified:false});biLog("cfg.edit","payer","",g("name"));biChanged();return true}});return}
  if(c("[data-bitf]")){biDialog(L4("Référence officielle sourcée|Sourced official reference|Amtliche Referenz|مرجع رسمي موثق"),`<p class="bi-note warn">${bii("warn",14)}${biE(L4("Saisissez uniquement des valeurs tirées d’une publication officielle, avec sa référence et sa version.|Enter only values taken from an official publication, with its reference and version.|Nur Werte aus amtlichen Quellen eingeben.|أدخل قيمًا من مصادر رسمية فقط."))}</p><div class="bi-flds"><div class="bi-fld"><label>${biE(L4("Système|System|System|النظام"))}</label><select class="bi-in" data-tv="sys">${biOpts([["CCAM","CCAM (FR)"],["NGAP","NGAP (FR)"],["TN","Tunisie — nomenclature à préciser"],["other","Autre"]],"NGAP")}</select></div><div class="bi-fld"><label>Code</label><input class="bi-in" data-tv="code" autofocus></div><div class="bi-fld full"><label>${biE(L4("Libellé officiel|Official label|Amtliche Bezeichnung|التسمية الرسمية"))}</label><input class="bi-in" data-tv="label"></div><div class="bi-fld"><label>${biE(L4("Tarif de référence (facultatif)|Reference tariff (optional)|Referenztarif|التعرفة المرجعية"))}</label><input class="bi-in num" data-tv="amount"></div><div class="bi-fld"><label>${biE(L4("Version / date d’effet|Version / effective date|Version|الإصدار"))}</label><input class="bi-in" data-tv="ver"></div><div class="bi-fld full"><label>${biE(L4("Source (document ou adresse officielle)|Source (official document or address)|Quelle|المصدر"))}</label><input class="bi-in" data-tv="src"></div></div>`,
   {onOk:m=>{const g=(k: string)=>m.querySelector<HTMLInputElement>(`[data-tv="${k}"]`)!.value.trim();if(!g("code")||!g("label")||!g("src")||!g("ver"))throw new BiErr("bi_eReq",L4("code, libellé, source et version|code, label, source and version|Code, Bezeichnung, Quelle, Version|الرمز والتسمية والمصدر والإصدار"));if((S!.tariffs||[]).some(t=>t.code===g("code")&&t.sys===g("sys")))throw new BiErr("bi_eGeneric");(S!.tariffs=S!.tariffs||[]).push({sys:g("sys"),code:g("code"),label:g("label"),amount:g("amount")?biParseMoney(g("amount")):null,ver:g("ver"),src:g("src"),verified:false});biLog("cfg.edit","tariff",g("code"),g("sys")+" "+g("code"));biChanged();return true}})}},
 change:e=>{const x=tgt(e);if(x.matches("[data-bitfv]")){const t=BI.st!.tariffs.find(z=>z.code===x.dataset.bitfv);t!.verified=x.checked;t!.verifiedBy=x.checked?"Nassim · "+biToday():null;biLog("cfg.edit","tariff",t!.code,(x.checked?"verified":"unverified"));biChanged()}}});

/* ---------- invoice template designer ---------- */
biDef("templates","bill",{n:"Modèles de facture|Invoice templates|Rechnungsvorlagen|قوالب الفواتير",ic:"palette",perm:"inv.view",page:()=>{const S=BI.st;const T=S!.templates.find(t=>t.id===BI.ui.tpl)||S!.templates.find(t=>t.id===S!.set.tpl)||S!.templates[0];BI.ui.tpl=T.id;const ed=biCan("tpl.edit");const mand=BI_MANDATORY[S!.set.juris]||BI_MANDATORY.other;const sample=S!.invoices.find(i=>i.status==="issued"&&i.snap!.lines.length>1&&!biCredited(i))||S!.invoices.find(i=>i.status==="issued"&&!biCredited(i));
  const allB=Object.keys(BI_BLOCKS);const order=T.blocks.concat(allB.filter(b=>!T.blocks.includes(b)));
  return `<div class="bi-tpl"><aside class="bi-card bi-tplist"><h3>${bii("palette",16)}${biE(L4("Modèles|Templates|Vorlagen|القوالب"))}</h3><ul>${S!.templates.map(t=>`<li><button type="button" data-bitpl="${t.id}" aria-current="${t.id===T.id}"><i style="background:${biE(t.accent)}"></i><span>${biE(t.name)}</span>${S!.set.tpl===t.id?`<em>${biE(L4("par défaut|default|Standard|افتراضي"))}</em>`:""}</button></li>`).join("")}</ul>${ed?`<button type="button" class="bi-btn sm" data-bitpladd>${bii("copy",14)}${biE(L4("Dupliquer ce modèle|Duplicate this template|Vorlage duplizieren|تكرار القالب"))}</button>`:""}</aside>
   <section class="bi-card bi-tpled"><h3>${bii("layers",16)}${biE(L4("Blocs du document|Document blocks|Dokumentblöcke|كتل المستند"))}</h3><ul class="bi-blocks">${order.map((b,i)=>{const on=T.blocks.includes(b),lock=mand.includes(b);return `<li class="${on?"on":""}" data-blk="${b}"><span class="drag">${bii("drag",14)}</span><label class="bi-chk"><input type="checkbox" data-bitb="${b}"${on?" checked":""}${!ed||lock?" disabled":""}><span>${biE(L4(BI_BLOCKS[b]))}</span></label>${lock?`<em title="${biE(L4("Obligatoire pour la juridiction|Mandatory for the jurisdiction|Pflicht|إلزامي"))}">${bii("lock",13)}${biE(L4("obligatoire|mandatory|Pflicht|إلزامي"))}</em>`:""}<span class="sp"></span>${ed&&on?`<button type="button" class="bi-ib sm" data-bitm="${b}|-1" aria-label="${biE(L4("Monter|Up|Hoch|أعلى"))}">${bii("up",13)}</button><button type="button" class="bi-ib sm" data-bitm="${b}|1" aria-label="${biE(L4("Descendre|Down|Runter|أسفل"))}">${bii("down",13)}</button>`:""}</li>`}).join("")}</ul>
    <div class="bi-flds"><div class="bi-fld"><label>${biE(L4("Nom|Name|Name|الاسم"))}</label><input class="bi-in" data-bitv="name" value="${biE(T.name)}"${ed?"":" disabled"}></div><div class="bi-fld"><label>${biE(L4("Couleur d’accent|Accent colour|Akzentfarbe|اللون"))}</label><input type="color" class="bi-in color" data-bitv="accent" value="${biE(T.accent)}"${ed?"":" disabled"}></div><div class="bi-fld"><label>${biE(L4("Police|Font|Schrift|الخط"))}</label><select class="bi-in" data-bitv="font"${ed?"":" disabled"}>${biOpts([["sans","Sans serif"],["serif","Serif"]],T.font)}</select></div><div class="bi-fld"><label>${biE(L4("Langue du document|Document language|Dokumentsprache|لغة المستند"))}</label><select class="bi-in" data-bitv="lang"${ed?"":" disabled"}>${biOpts([["auto",L4("Langue de l’interface|Interface language|Oberflächensprache|لغة الواجهة")],["fr","Français"],["en","English"],["de","Deutsch"],["ar","العربية"]],T.lang||"auto")}</select></div>
     <div class="bi-fld full"><label>${biE(L4("Titre du document (libellé personnalisé)|Document title (custom label)|Dokumenttitel|عنوان المستند"))}</label><input class="bi-in" data-bitl="inv" value="${biE(T.labels?.inv||"")}" placeholder="${biE(biDL("inv",biDocLang(T)))}"${ed?"":" disabled"}></div><div class="bi-fld full"><label>${biE(L4("Libellé « Total »|“Total” label|„Gesamt“-Bezeichnung|تسمية المجموع"))}</label><input class="bi-in" data-bitl="total" value="${biE(T.labels?.total||"")}" placeholder="${biE(biDL("total",biDocLang(T)))}"${ed?"":" disabled"}></div></div>
    <div class="bi-acts">${ed&&S!.set.tpl!==T.id?`<button type="button" class="bi-btn" data-bitpldef>${bii("star",14)}${biE(L4("Utiliser par défaut|Use as default|Als Standard|استخدام افتراضيًا"))}</button>`:""}${ed&&S!.templates.length>1&&S!.set.tpl!==T.id?`<button type="button" class="bi-btn danger" data-bitpldel>${bii("trash",14)}${biE(biW("del"))}</button>`:""}<span class="sp"></span><button type="button" class="bi-btn" data-bitplprint>${bii("print",14)}${biE(L4("Aperçu impression|Print preview|Druckvorschau|معاينة الطباعة"))}</button></div><p class="bi-mut sm">${biE(L4("Les mentions légales obligatoires restent imposées par la juridiction ; un modèle modifie la présentation, jamais le contenu légal ni les montants. Les factures déjà émises gardent leur instantané.|Mandatory legal mentions stay imposed by the jurisdiction; a template changes presentation, never legal content or amounts. Issued invoices keep their snapshot.|Pflichtangaben bleiben; Vorlage ändert nur die Darstellung.|القالب يغير العرض فقط."))}</p></section>
   <section class="bi-tplpv"><div class="bi-edpvh"><b>${bii("eye",15)}${biE(L4("Aperçu avec une facture fictive|Preview with a fictitious invoice|Vorschau mit fiktiver Rechnung|معاينة بفاتورة وهمية"))}</b></div><div class="bi-docw" data-bitplpv>${sample?biDocHTML(sample,{tpl:T}):""}</div></section></div>`},
 mount:R=>{biFitDocs(R);setTimeout(()=>biFitDocs(R),50)},
 click:(e,c)=>{const S=BI.st;let x: HTMLInputElement | null;const T=S!.templates.find(t=>t.id===BI.ui.tpl);if((x=c("[data-bitpl]"))){BI.ui.tpl=x.dataset.bitpl;biRefresh();return}
  if(c("[data-bitpladd]")){const n=biClone(T);n!.id=biId("t");n!.name=T!.name+" (2)";S!.templates.push(n!);BI.ui.tpl=n!.id;biLog("tpl.edit","tpl",n!.id,n!.name);biChanged();return}
  if(c("[data-bitpldef]")){S!.set.tpl=T!.id;biLog("tpl.edit","tpl",T!.id,T!.name+" → default");biChanged();return}
  if(c("[data-bitpldel]")){biConfirm(L4("Supprimer ce modèle ? Les factures émises avec lui gardent leur instantané.|Delete this template? Invoices issued with it keep their snapshot.|Vorlage löschen?|حذف القالب؟"),()=>{S!.templates=S!.templates.filter(t=>t!==T);S!.invoices.forEach(i=>{if(i.status==="draft"&&i.tpl===T!.id)i.tpl=S!.set.tpl});BI.ui.tpl=S!.set.tpl;biLog("tpl.edit","tpl",T!.id,T!.name+" ✕");biChanged()},{danger:true,okLabel:biW("del")});return}
  if(c("[data-bitplprint]")){const sample=S!.invoices.find(i=>i.status==="issued");if(sample)biPrint(biDocHTML(sample,{tpl:T}),T!.name);return}
  if((x=c("[data-bitm]"))){const [b,d]=x.dataset.bitm!.split("|");const i=T!.blocks.indexOf(b),j=i+ +d;if(j<0||j>=T!.blocks.length)return;[T!.blocks[i],T!.blocks[j]]=[T!.blocks[j],T!.blocks[i]];biTplSaved(T!)}},
 change:e=>{const S=BI.st;const T=S!.templates.find(t=>t.id===BI.ui.tpl);const x=tgt(e);if(x.matches("[data-bitb]")){const b=x.dataset.bitb;const mand=BI_MANDATORY[S!.set.juris]||BI_MANDATORY.other;if(!x.checked&&mand.includes(b!)){x.checked=true;biToast(biErr(new BiErr("bi_eMandatory",L4(BI_BLOCKS[b!]))));return}if(x.checked)T!.blocks.push(b!);else T!.blocks=T!.blocks.filter(z=>z!==b);biTplSaved(T!);return}
  if(x.matches("[data-bitv]")){(T as unknown as Dict)[x.dataset.bitv!]=x.value;biTplSaved(T!,true);return}if(x.matches("[data-bitl]")){T!.labels=T!.labels||{};if(x.value.trim())T!.labels[x.dataset.bitl!]=x.value.trim();else delete T!.labels[x.dataset.bitl!];biTplSaved(T!,true)}},
 input:e=>{const x=tgt(e);if(x.matches("[data-bitv=accent]")){const T=BI.st!.templates.find(t=>t.id===BI.ui.tpl);T!.accent=x.value;const pv=biRoot()!.querySelector<HTMLInputElement>("[data-bitplpv] .bi-doc");if(pv){pv.style.setProperty("--acc",x.value);pv.querySelectorAll<HTMLInputElement>("h1,.d-mono").forEach(h=>{if(h.tagName==="H1")h.style.color=x.value;else h.style.background=x.value})}}}});
function biTplSaved(T: BiTpl,soft?: boolean){biLog("tpl.edit","tpl",T.id,T.name);biSave();if(soft){const R=biRoot();const pv=R!.querySelector<HTMLInputElement>("[data-bitplpv]");const S=BI.st;const sample=S!.invoices.find(i=>i.status==="issued"&&i.snap!.lines.length>1&&!biCredited(i))||S!.invoices.find(i=>i.status==="issued"&&!biCredited(i));if(pv&&sample){pv.innerHTML=biDocHTML(sample,{tpl:T});biFitDocs(R)}R!.querySelectorAll<HTMLInputElement>(`[data-bitpl="${T.id}"] span`).forEach(s=>s.textContent=T.name);return}
  const R=biRoot();const before=[...R!.querySelectorAll<HTMLInputElement>("[data-blk]")].map(n=>[n.dataset.blk,n.getBoundingClientRect().top] as [string, number]);biRefresh();if(!biRM())before.forEach(([b,t])=>{const n=R!.querySelector<HTMLInputElement>(`[data-blk="${b}"]`);if(!n)return;const d=t-n.getBoundingClientRect().top;if(d)n.animate([{transform:`translateY(${d}px)`},{transform:"none"}],{duration:280,easing:"cubic-bezier(.2,.9,.3,1)"})})}

/* ---------- configuration ---------- */
function biCfgField(l: string,ctl: string,o: { full?: boolean | number; hint?: string }={}){return `<div class="bi-fld${o.full?" full":""}"><label>${biE(L4(l))}</label>${ctl}${o.hint?`<small>${biE(L4(o.hint))}</small>`:""}</div>`}
biDef("settings","cfg",{n:"Paramètres de facturation|Billing settings|Abrechnungseinstellungen|إعدادات الفوترة",ic:"gear",perm:"cat.view",page:()=>{const S=BI.st;const ed=biCan("cfg.edit");const dis=ed?"":" disabled";return `<div class="bi-cfg"><section class="bi-card"><h3>${bii("gear",16)}${biE(L4("Général|General|Allgemein|عام"))}</h3><div class="bi-flds">
  ${biCfgField("Devise|Currency|Währung|العملة",`<select class="bi-in" data-bis="cur"${dis}>${biOpts(Object.keys(BI_CUR).map(c=>[c,c+" ("+BI_CUR[c].s+")"]),S!.set.cur)}</select>`,{hint:"Les montants existants ne sont pas convertis : changez la devise avant de facturer.|Existing amounts are not converted: change the currency before invoicing.|Bestehende Beträge werden nicht umgerechnet.|المبالغ الحالية لا تُحوّل."})}
  ${biCfgField("Juridiction|Jurisdiction|Rechtsraum|الولاية القضائية",`<select class="bi-in" data-bis="juris"${dis}>${biOpts([["FR","France"],["TN","Tunisie"],["other",L4("Autre (configuration manuelle)|Other (manual)|Andere|أخرى")]],S!.set.juris)}</select>`,{hint:"Détermine les blocs obligatoires et les taux proposés ; ne remplace pas un avis juridique.|Sets mandatory blocks and suggested rates; not legal advice.|Bestimmt Pflichtblöcke; keine Rechtsberatung.|يحدد الكتل الإلزامية."})}
  ${biCfgField("Conditions de paiement par défaut|Default payment terms|Standard-Zahlungsziel|الشروط الافتراضية",`<select class="bi-in" data-bis="terms"${dis}>${biOpts(S!.terms.map(t=>[t.days,L4(t.n)]),S!.set.terms)}</select>`)}
  ${biCfgField("Modèle par défaut|Default template|Standardvorlage|القالب الافتراضي",`<select class="bi-in" data-bis="tpl"${dis}>${biOpts(S!.templates.map(t=>[t.id,t.name]),S!.set.tpl)}</select>`)}</div></section>
  <section class="bi-card"><h3>${bii("calCheck",16)}${biE(L4("Absences et annulations|No-shows and cancellations|Ausfälle und Absagen|الغياب والإلغاء"))}</h3><label class="bi-chk"><input type="checkbox" data-bis="noshow.on"${S!.set.noshow?.on?" checked":""}${dis}><span>${biE(L4("Facturer les rendez-vous non honorés selon la politique du cabinet (information préalable du patient requise)|Bill missed appointments per the practice policy (patient must be informed beforehand)|Ausfälle gemäß Praxisrichtlinie abrechnen|فوترة المواعيد الفائتة"))}</span></label><div class="bi-flds">${biCfgField("Montant forfaitaire|Flat fee|Pauschale|المبلغ",`<input class="bi-in num" data-bis="noshow.fee" value="${biE(biM(S!.set.noshow?.fee||0,null,{plain:true}))}"${dis}>`)}</div><p class="bi-mut sm">${biE(L4("Les annulations n’entraînent jamais de facturation automatique : un brouillon est préparé seulement si un utilisateur le demande.|Cancellations never trigger automatic billing: a draft is prepared only when a user asks.|Absagen lösen keine automatische Abrechnung aus.|الإلغاء لا يسبب فوترة تلقائية."))}</p></section>
  <section class="bi-card"><h3>${bii("dl",16)}${biE(L4("Données|Data|Daten|البيانات"))}</h3><p class="bi-mut">${biE(L4("Les données de facturation sont stockées dans ce navigateur (aucun serveur). Exportez-les régulièrement.|Billing data is stored in this browser (no server). Export it regularly.|Daten liegen im Browser; regelmäßig exportieren.|البيانات مخزنة في هذا المتصفح."))}</p><div class="bi-acts"><button type="button" class="bi-btn" data-bijson>${bii("dl",14)}${biE(L4("Exporter toutes les données (JSON)|Export all data (JSON)|Alle Daten exportieren (JSON)|تصدير كل البيانات"))}</button><button type="button" class="bi-btn" data-bisales>${bii("dl",14)}${biE(L4("Journal des ventes (CSV)|Sales journal (CSV)|Ausgangsjournal (CSV)|دفتر المبيعات"))}</button>${ed?`<span class="sp"></span><button type="button" class="bi-btn danger" data-bireseed>${bii("undo",14)}${biE(L4("Régénérer les données fictives|Regenerate demo data|Demodaten neu erzeugen|إعادة توليد البيانات"))}</button>`:""}</div></section></div>`},
 change:e=>{const x=tgt(e);if(!x.matches("[data-bis]"))return;const S=BI.st;const k=x.dataset.bis;if(k==="noshow.on"){S!.set.noshow.on=x.checked}else if(k==="noshow.fee"){try{S!.set.noshow.fee=biParseMoney(x.value)||0}catch(err){biToast(biErr(err));return}}else if(k==="terms")S!.set.terms=+x.value;else if(k==="juris"){S!.set.juris=x.value;if(x.value==="TN"&&confirm(L4("Charger les catégories de TVA proposées pour la Tunisie (à vérifier) ?|Load the suggested Tunisian tax categories (to verify)?|Tunesische Kategorien laden?|تحميل فئات تونس؟"))){S!.taxes=biClone(BI_TAX_TN)}if(x.value==="FR"&&!S!.taxes.some(t=>t.id==="n20"))S!.taxes=biClone(BI_TAX_FR)}else S!.set[k!]=x.value;biLog("cfg.edit","set",k!,String(x.type==="checkbox"?x.checked:x.value));biChanged();biToast(biW("saved"))},
 click:(e,c)=>{const S=BI.st;if(c("[data-bijson]")){biDownload(`facturation-${biToday()}.json`,JSON.stringify({remotionBilling:1,exported:new Date().toISOString(),synthetic:!!S!.synthetic,data:S},null,1),"application/json");return}
  if(c("[data-bisales]")){const rows: [string, ...unknown[]][]=[];S!.invoices.filter(i=>i.status==="issued").forEach(i=>i.snap!.tot.rates.forEach(r=>rows.push([i.issue,i.no,"FACTURE",biPartyName(i.party),r.tax,biM(r.base,null,{plain:true}),biM(r.amt,null,{plain:true}),biM(r.base+r.amt,null,{plain:true})])));S!.credits.forEach(cn=>cn.snap!.tot.rates.forEach(r=>rows.push([cn.issue,cn.no,"AVOIR",biPartyName(cn.party),r.tax,"-"+biM(r.base,null,{plain:true}),"-"+biM(r.amt,null,{plain:true}),"-"+biM(r.base+r.amt,null,{plain:true})])));rows.sort((a,b)=>a[0]<b[0]?-1:1);biDownload(`journal-ventes-${biToday()}.csv`,biCsv(["Date","Pièce","Type","Client","Catégorie TVA","Base HT","TVA","TTC"],rows));return}
  if(c("[data-bireseed]")){biConfirm(L4("Remplacer toutes les données de facturation de ce navigateur par un nouveau jeu fictif ?|Replace all billing data in this browser with a new fictitious set?|Alle Daten durch neue Demodaten ersetzen?|استبدال كل البيانات؟"),()=>{biReset();BI.ui.stack=[];biRender(true);biToast(biW("saved"))},{danger:true})}}});
biDef("numbering","cfg",{n:"Séquences de numérotation|Numbering sequences|Nummernkreise|تسلسلات الترقيم",ic:"hash",perm:"cat.view",page:()=>{const S=BI.st;const ed=biCan("cfg.edit");const K=[["inv","Factures|Invoices|Rechnungen|الفواتير"],["cn","Avoirs|Credit notes|Gutschriften|الإشعارات"],["qt","Devis|Quotes|Angebote|العروض"],["pay","Paiements (reçus)|Payments (receipts)|Zahlungen|المدفوعات"],["rf","Remboursements|Refunds|Erstattungen|الاستردادات"]];
  return `<p class="bi-desc">${biE(L4("Factures et avoirs suivent une numérotation continue et chronologique, sans trou ni doublon. Le préfixe et le format peuvent changer pour les prochaines pièces ; les compteurs ne peuvent jamais revenir en arrière.|Invoices and credit notes follow a continuous, chronological sequence with no gaps or duplicates. Prefix and format can change for future documents; counters can never go backwards.|Fortlaufende, lückenlose Nummerierung; Zähler nie rückwärts.|ترقيم متسلسل دون فجوات."))}</p><div class="bi-tbs"><table class="bi-tb"><thead><tr><th>${biE(L4("Série|Series|Serie|السلسلة"))}</th><th>${biE(L4("Préfixe|Prefix|Präfix|البادئة"))}</th><th>${biE(L4("Chiffres|Digits|Stellen|الأرقام"))}</th><th>${biE(L4("Remise à zéro|Reset|Zurücksetzen|إعادة الضبط"))}</th><th>${biE(L4("Dernier numéro attribué|Last number issued|Letzte Nummer|آخر رقم"))}</th><th>${biE(L4("Prochain numéro|Next number|Nächste Nummer|الرقم التالي"))}</th></tr></thead><tbody>${K.map(([k,l])=>{const s=S!.seqs[k]||BI_SEQ_DEF[k];const y=s.reset==="year"?biToday().slice(0,4):"all";const last=(s.c||{})[y];return `<tr><th>${biE(L4(l))}</th><td><input class="bi-in sm" data-biseq="${k}|p" value="${biE(s.p)}" maxlength="6"${ed?"":" disabled"}></td><td><select class="bi-in sm" data-biseq="${k}|pad"${ed?"":" disabled"}>${biOpts([4,5,6,7].map(n=>[n,n]),s.pad)}</select></td><td><select class="bi-in sm" data-biseq="${k}|reset"${ed?"":" disabled"}>${biOpts([["year",L4("Chaque année|Yearly|Jährlich|سنويًا")],["never",L4("Jamais|Never|Nie|أبدًا")]],s.reset)}</select></td><td class="bi-mono">${last?biE(biFmtNo(k,y==="all"?"":y,last)):"—"}</td><td class="bi-mono"><b>${biE(biPeekNo(k,biToday()))}</b></td></tr>`}).join("")}</tbody></table></div>`},
 change:e=>{const x=tgt(e);if(!x.matches("[data-biseq]"))return;const [k,f]=x.dataset.biseq!.split("|");const S=BI.st;const s=S!.seqs[k]=S!.seqs[k]||biClone(BI_SEQ_DEF[k]);let v=x.value.trim();if(f==="p"){v=v.toUpperCase().replace(/[^A-Z0-9]/g,"");if(!v){biToast(biErr(new BiErr("bi_eReq",L4("Préfixe|Prefix|Präfix|البادئة"))));return}}
  if(f==="reset"&&v!==s.reset){const y=biToday().slice(0,4);s.c=s.c||{};if(v==="never"){s.c.all=Object.values(s.c).reduce((a,b)=>a+b,0)}else{s.c[y]=Math.max(s.c[y]||0,0)}}(s as unknown as Bag)[f]=f==="pad"?+v:v;biLog("cfg.edit","seq",k,f+" = "+v);biChanged()}});
biDef("legal","cfg",{n:"Informations légales|Legal and business information|Rechtliche Angaben|المعلومات القانونية",ic:"shield",perm:"cat.view",page:()=>{const S=BI.st;const L=S!.legal;const ed=biCan("cfg.edit");const F: [string, string, number?][]=[["name","Raison sociale|Legal name|Firmenname|الاسم القانوني",1],["form","Forme juridique|Legal form|Rechtsform|الشكل القانوني"],["addr","Adresse du siège|Registered address|Anschrift|العنوان",1],["siret",S!.set.juris==="FR"?"SIRET|SIRET|SIRET|SIRET":"N° d’immatriculation|Registration no.|Registernummer|رقم التسجيل"],["vat","N° de TVA intracommunautaire (si assujetti)|VAT number (if liable)|USt-IdNr.|الرقم الضريبي"],["phone","Téléphone|Phone|Telefon|الهاتف"],["email","E-mail de facturation|Billing email|Rechnungs-E-Mail|بريد الفوترة"],["iban","IBAN|IBAN|IBAN|IBAN"],["bic","BIC|BIC|BIC|BIC"],["footer","Pied de page|Footer|Fußzeile|التذييل",1],["logo","Logo (adresse d’image ou data:)|Logo (image URL or data:)|Logo (Bild-URL)|الشعار",1]];
  return `<section class="bi-card"><p class="bi-desc">${biE(L4("Ces informations figurent sur chaque document. Une modification crée une nouvelle version : les factures déjà émises conservent la version en vigueur au moment de leur émission.|These details appear on every document. A change creates a new version: issued invoices keep the version in force when they were issued.|Änderungen erzeugen eine neue Version.|التعديل ينشئ إصدارًا جديدًا."))} ${biNf(Object.keys(S!.legalVers||{}).length)} ${biE(L4("version(s) référencée(s).|version(s) referenced.|Version(en).|إصدار."))}</p><div class="bi-flds">${F.map(([k,l,full])=>biCfgField(l,`<input class="bi-in" data-bilg="${k}" value="${biE(L[k]||"")}"${ed?"":" disabled"}>`,{full}))}</div></section>
   <section class="bi-card"><h3>${bii("building",16)}${biE(L4("Établissements|Establishments|Einrichtungen|المؤسسات"))}</h3><ul class="bi-list">${S!.ests.map(e=>`<li><span class="ic">${bii("pin",14)}</span><div><b>${biE(e.name)}</b><small>${biE(e.addr)}${e.finess?" · FINESS "+biE(e.finess):""}</small></div></li>`).join("")}</ul><h3>${bii("users",16)}${biE(L4("Praticiens|Practitioners|Behandler|الممارسون"))}</h3><ul class="bi-list">${S!.pracs.map(p=>`<li><span class="ic">${bii("user",14)}</span><div><b>${biE(p.name)}</b><small>${biE(L4(BI_PROFS[p.prof]))} · RPPS ${p.rpps?biE(p.rpps):`<em class="bi-warnt">${biE(L4("non renseigné|not set|nicht gesetzt|غير محدد"))}</em>`} · ${biE(L4({liberal:"Libéral|Self-employed|Selbstständig|حر",employee:"Salarié|Employee|Angestellt|موظف",contractor:"Prestataire|Contractor|Auftragnehmer|متعاقد"}[p.status]!))}</small></div>${ed?`<button type="button" class="bi-btn sm" data-birpps="${p.id}">${biE(L4("Identifiant|Identifier|Kennung|المعرف"))}</button>`:""}</li>`).join("")}</ul><p class="bi-mut sm">${biE(L4("Les fiches praticiens et établissements complètes relèvent des applications Organisation et RH ; la facturation n’en garde que ce qui doit figurer sur les documents.|Full practitioner and establishment records belong to the Organisation and HR apps; billing keeps only what must appear on documents.|Vollständige Stammdaten in Organisation/HR.|السجلات الكاملة في تطبيق المؤسسة."))}</p></section>`},
 change:e=>{const x=tgt(e);if(x.matches("[data-bilg]")){BI.st!.legal[x.dataset.bilg!]=x.value.trim();biLog("cfg.edit","legal",x.dataset.bilg!,x.value.trim().slice(0,60));biSave();biToast(biW("saved"))}},
 click:(e,c)=>{const x=c("[data-birpps]");if(x){const p=BI.st!.pracs.find(z=>z.id===x.dataset.birpps);biPrompt(L4("Identifiant professionnel (RPPS/ADELI)|Professional identifier|Berufskennung|المعرف المهني"),p!.rpps,v=>{p!.rpps=v;biLog("cfg.edit","prac",p!.id,p!.name);biChanged()})}}});
biDef("terms","cfg",{n:"Conditions de paiement|Payment terms|Zahlungsbedingungen|شروط الدفع",ic:"clock",perm:"cat.view",page:()=>{const S=BI.st;const ed=biCan("cfg.edit");return `<section class="bi-card"><ul class="bi-list">${S!.terms.map((t,i)=>`<li><span class="ic">${bii("clock",14)}</span><div><b>${biE(L4(t.n))}</b><small>${biNf(t.days)} ${biE(L4("jours après émission|days after issue|Tage nach Ausstellung|يومًا بعد الإصدار"))}</small></div>${S!.set.terms===t.days?`<span class="bi-st ok">${biE(L4("par défaut|default|Standard|افتراضي"))}</span>`:""}${ed&&S!.terms.length>1&&S!.set.terms!==t.days?`<button type="button" class="bi-ib sm" data-bitrd="${i}" aria-label="${biE(biW("del"))}">${bii("trash",14)}</button>`:""}</li>`).join("")}</ul>${ed?`<div class="bi-acts"><button type="button" class="bi-btn" data-bitra>${bii("plus",14)}${biE(L4("Ajouter des conditions|Add terms|Bedingung hinzufügen|إضافة شروط"))}</button></div>`:""}<p class="bi-mut sm">${biE(L4("Pour une clientèle professionnelle, la loi peut imposer des mentions de pénalités de retard ; ajoutez-les dans le pied de page si elles s’appliquent.|For business customers, the law may require late-payment penalty mentions; add them to the footer when applicable.|Für Geschäftskunden ggf. Verzugshinweise im Fußtext.|للعملاء المهنيين قد تلزم عبارات غرامات التأخير."))}</p></section>`},
 click:(e,c)=>{const S=BI.st;let x: HTMLInputElement | null;if((x=c("[data-bitrd]"))){S!.terms.splice(+x.dataset.bitrd!,1);biChanged();return}if(c("[data-bitra]")){biDialog(L4("Conditions de paiement|Payment terms|Zahlungsbedingungen|شروط الدفع"),`<div class="bi-flds"><div class="bi-fld"><label>${biE(L4("Jours|Days|Tage|أيام"))}</label><input class="bi-in num" data-trv="days" inputmode="numeric" autofocus></div><div class="bi-fld"><label>${biE(L4("Libellé imprimé|Printed label|Gedruckter Text|التسمية"))}</label><input class="bi-in" data-trv="n"></div></div>`,{onOk:m=>{const d=parseInt(m.querySelector<HTMLInputElement>("[data-trv=days]")!.value,10);if(!(d>=0&&d<=365))throw new BiErr("bi_eReq",L4("Jours|Days|Tage|أيام"));if(S!.terms.some(t=>t.days===d))throw new BiErr("bi_eGeneric");const n=m.querySelector<HTMLInputElement>("[data-trv=n]")!.value.trim()||d+" jours";S!.terms.push({days:d,n:biSetL4("",n)});S!.terms.sort((a,b)=>a.days-b.days);biLog("cfg.edit","terms","",n);biChanged();return true}})}}});
biDef("integrations","cfg",{n:"Intégrations|Integrations|Integrationen|التكاملات",ic:"plug",perm:"cat.view",page:()=>{const I=[["pay","card","Prestataire de paiement|Payment provider|Zahlungsanbieter|مزود الدفع","Adaptateur prévu pour un prestataire (paiement en ligne, terminal). Tant qu’il n’est pas connecté, aucune demande de paiement n’est envoyée et rien n’est compté comme encaissé sans enregistrement.|Adapter for a provider (online, terminal). Until connected, no payment request is sent and nothing counts as collected without a recorded payment.|Adapter für Zahlungsanbieter; nicht verbunden.|محول لمزود الدفع؛ غير متصل.","notconn"],
   ["einv","send","Facturation électronique|E-invoicing|E-Rechnung|الفوترة الإلكترونية","Format structuré et plateforme de dématérialisation selon la juridiction. Non implémenté : aucune conformité n’est revendiquée.|Structured format and platform per jurisdiction. Not implemented: no compliance is claimed.|Nicht implementiert; keine Konformität behauptet.|غير منفذ.","notconn"],
   ["pdf","print","Génération de documents|Document generation|Dokumenterzeugung|إنشاء المستندات","Impression navigateur au format A4 (« Enregistrer en PDF » dans la boîte d’impression). Le moteur PDF de Documents peut être branché plus tard.|Browser A4 printing (“Save as PDF” in the print dialog). The Documents PDF engine can be plugged in later.|Browserdruck A4 („Als PDF speichern“).|طباعة المتصفح.","connected"],
   ["ref","lib","Référentiels officiels (CCAM, NGAP…)|Official references (CCAM, NGAP…)|Amtliche Referenzen|المراجع الرسمية","Import d’un référentiel versionné depuis une source officielle. Non connecté : saisie manuelle sourcée et vérifiée uniquement.|Import of a versioned reference from an official source. Not connected: manual, sourced and verified entry only.|Nicht verbunden; nur manuelle Eingabe.|غير متصل.","notconn"],
   ["acc","dl","Export comptable|Accounting export|Buchhaltungsexport|التصدير المحاسبي","Journal des ventes CSV disponible dans Paramètres. Un export au format exigé par l’administration fiscale n’est pas fourni.|CSV sales journal available in Settings. A tax-authority format export is not provided.|CSV-Journal in Einstellungen.|دفتر المبيعات CSV متاح.","connected"],
   ["forms","form","Application Formulaires|Forms app|Formulare-App|تطبيق الاستمارات","Lecture des formulaires et de leurs champs pour les rattacher aux prestations. L’application Formulaires reste générique et n’est pas modifiée.|Reads forms and their fields to link them to services. The Forms app stays generic and unchanged.|Liest Formulare; Formulare-App bleibt unverändert.|قراءة الاستمارات فقط.","connected"],
   ["hr","users","RH & Paie|HR & Payroll|HR & Lohn|الموارد البشرية والرواتب","La répartition des honoraires peut alimenter la paie ; le calcul de paie reste dans l’application RH & Paie, non connectée ici.|Fee allocation can feed payroll; payroll stays in the HR & Payroll app, not connected here.|Lohn bleibt in HR & Payroll.|الرواتب في تطبيق الموارد البشرية.","notconn"],
   ["cal","cal","Agenda et dossiers patients|Calendar and patient records|Kalender und Patientenakten|التقويم والملفات","Les rendez-vous à facturer sont des exemples fictifs tant que l’agenda n’est pas une application réelle de l’OS.|Appointments to bill are fictitious examples until the calendar is a real OS app.|Termine sind fiktiv.|المواعيد أمثلة وهمية.","notconn"]];
  return `<div class="bi-mgrid">${I.map(([k,ic,n,d,st],i)=>`<div class="bi-card bi-meth" style="--i:${i}"><header><span class="ic">${bii(ic,18)}</span><b>${biE(L4(n))}</b>${biSt8(st)}</header><p>${biE(L4(d))}</p></div>`).join("")}</div>`}});
biDef("audit","cfg",{n:"Historique d’audit|Audit history|Prüfprotokoll|سجل التدقيق",ic:"hist",perm:"audit.view",page:()=>{const f=biFlt("audit");const q=(f.q||"").toLowerCase();const [pf,pt]=biPerRange(f);const rows=BI.st!.audit.filter(a=>(!q||(biActName(a.act)+" "+a.detail+" "+a.user).toLowerCase().includes(q))&&biInRange(a.ts.slice(0,10),pf,pt)&&(!f.ent||a.ent===f.ent)).map(a=>({id:a.id,ts:a.ts,act:biActName(a.act),ent:a.ent,user:a.user,role:L4(BI_ROLES[a.role]?.n||a.role),detail:a.detail}));
  const cols: BiCol<(typeof rows)[number]>[]=[{k:"ts",l:"Horodatage|Timestamp|Zeitstempel|الطابع الزمني",v:r=>r.ts,h:r=>biE(new Date(r.ts).toLocaleString(biLoc(),{dateStyle:"short",timeStyle:"medium"}))},{k:"act",l:"Action|Action|Aktion|الإجراء",v:r=>r.act,h:r=>`<b>${biE(r.act)}</b>`},{k:"detail",l:"Détail|Detail|Detail|التفاصيل",v:r=>r.detail,h:r=>`<span class="bi-clip">${biE(r.detail)}</span>`},{k:"user",l:"Utilisateur|User|Benutzer|المستخدم",v:r=>r.user},{k:"role",l:"Rôle|Role|Rolle|الدور",v:r=>r.role}];BI_TBL.audit={cols,rows};
  return `<p class="bi-desc">${biE(L4("Chaque émission, paiement, avoir, remboursement, rapprochement et modification de configuration est journalisé. Ce journal local n’est pas infalsifiable : il ne remplace pas un système d’audit serveur.|Every issue, payment, credit note, refund, reconciliation and configuration change is logged. This local log is not tamper-proof: it does not replace a server audit system.|Lokales Protokoll, nicht manipulationssicher.|سجل محلي غير محمي من التلاعب."))}</p>${biFltHTML("audit",f,{prac:false,est:false})}${biTable("audit",cols,rows,{sort:"ts"})}`}});


